const VISUAL_DISPLAY_SETTING_KEYS = ["showIdBadges", "showRegionBadges", "showSelectionOutlines", "showSwapLayoutControls"] as const;
const DEBUG_SETTINGS_KEYS = ["enabled", "persistToProjectLogs", "includeDragRouting", "includeInvalidDrops"] as const;
const CANVAS_ACTION_VISIBILITY_KEYS = [
  "showDrag",
  "showAddChild",
  "showAddSibling",
  "showMoveUp",
  "showMoveDown",
  "showEdit",
  "showDuplicate",
  "showDelete",
] as const;

function clampPreviewScale(value: number): number {
  if (!Number.isFinite(value)) return DEFAULT_PREVIEW_SCALE;
  const clamped = Math.min(MAX_PREVIEW_SCALE, Math.max(MIN_PREVIEW_SCALE, value));
  return Math.round(clamped * 100) / 100;
}

function parsePreviewScaleSnapshot(candidate: unknown): number | null {
  if (typeof candidate !== "number" || !Number.isFinite(candidate)) return null;
  return clampPreviewScale(candidate);
}

function parseVisualDisplaySettingsSnapshot(candidate: unknown): VisualDisplaySettings | null {
  if (!candidate || typeof candidate !== "object") return null;
  const source = candidate as Record<string, unknown>;
  const next: Partial<VisualDisplaySettings> = {};
  for (const key of VISUAL_DISPLAY_SETTING_KEYS) {
    const value = source[key];
    if (typeof value === "boolean") {
      next[key] = value;
      continue;
    }
    if (value === undefined) {
      next[key] = DEFAULT_VISUAL_DISPLAY_SETTINGS[key];
      continue;
    }
    return null;
  }
  return next as VisualDisplaySettings;
}

function parseCanvasActionVisibilitySnapshot(candidate: unknown): CanvasActionVisibilitySettings | null {
  if (!candidate || typeof candidate !== "object") return null;
  const source = candidate as Record<string, unknown>;
  const next: Partial<CanvasActionVisibilitySettings> = {};
  for (const key of CANVAS_ACTION_VISIBILITY_KEYS) {
    const value = source[key];
    if (typeof value !== "boolean") return null;
    next[key] = value;
  }
  return next as CanvasActionVisibilitySettings;
}

function parseDebugSettingsSnapshot(candidate: unknown): DebugSettings | null {
  if (!candidate || typeof candidate !== "object") return null;
  const source = candidate as Record<string, unknown>;
  const next: Partial<DebugSettings> = {};
  for (const key of DEBUG_SETTINGS_KEYS) {
    const value = source[key];
    if (typeof value === "boolean") {
      next[key] = value;
      continue;
    }
    if (value === undefined) {
      next[key] = DEFAULT_DEBUG_SETTINGS[key];
      continue;
    }
    return null;
  }
  return next as DebugSettings;
}

function readStoredOptionsSettingsSnapshot(): StoredOptionsSettingsSnapshot | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(OPTIONS_SETTINGS_LOCAL_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as {
      visualDisplaySettings?: unknown;
      canvasActionVisibility?: unknown;
      debugSettings?: unknown;
      autoSaveOptionsEnabled?: unknown;
      previewScale?: unknown;
    };
    const visualDisplaySettings = parseVisualDisplaySettingsSnapshot(parsed.visualDisplaySettings);
    const canvasActionVisibility = parseCanvasActionVisibilitySnapshot(parsed.canvasActionVisibility);
    const debugSettings = parseDebugSettingsSnapshot(parsed.debugSettings) ?? { ...DEFAULT_DEBUG_SETTINGS };
    if (!visualDisplaySettings || !canvasActionVisibility) return null;
    const autoSaveOptionsEnabled =
      typeof parsed.autoSaveOptionsEnabled === "boolean"
        ? parsed.autoSaveOptionsEnabled
        : DEFAULT_OPTIONS_AUTO_SAVE_ENABLED;
    const previewScale = parsePreviewScaleSnapshot(parsed.previewScale) ?? DEFAULT_PREVIEW_SCALE;
    return { visualDisplaySettings, canvasActionVisibility, debugSettings, autoSaveOptionsEnabled, previewScale };
  } catch {
    return null;
  }
}

function writeStoredOptionsSettingsSnapshot(snapshot: StoredOptionsSettingsSnapshot): boolean {
  if (typeof window === "undefined") return false;
  try {
    window.localStorage.setItem(OPTIONS_SETTINGS_LOCAL_STORAGE_KEY, JSON.stringify(snapshot));
    return true;
  } catch {
    return false;
  }
}

