function humanizeComponentName(name: string): string {
  const withoutPrefix = name.startsWith("Nui") ? name.slice(3) : name;
  if (!withoutPrefix) return name;
  return withoutPrefix
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z])([A-Z][a-z])/g, "$1 $2")
    .toLowerCase();
}

function humanizeArgName(name: string): string {
  const raw = name.trim();
  if (!raw) return raw;
  const withoutPrefix = raw.length > 1 ? raw.replace(/^[jsnfb]/, "") : raw;
  return withoutPrefix
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z])([A-Z][a-z])/g, "$1 $2")
    .toLowerCase();
}

function describeSlot(slot: "none" | "single" | "list"): string {
  if (slot === "single") return "accepts one child";
  if (slot === "list") return "accepts multiple children";
  return "leaf component";
}

function comparePaletteCategoryOrder(a: string, b: string): number {
  const aIsCustom = a === "Custom";
  const bIsCustom = b === "Custom";
  if (aIsCustom && !bIsCustom) return 1;
  if (!aIsCustom && bIsCustom) return -1;
  return a.localeCompare(b);
}

function getPaletteComponentDescription(component: NuiComponent): string {
  const override = PALETTE_COMPONENT_DESCRIPTION_OVERRIDES[component.name];
  if (override) return override;

  const extraArgs = component.args
    .filter((_, idx) => idx !== component.structuralArgIndex)
    .slice(0, 3)
    .map((arg) => humanizeArgName(arg.name))
    .filter(Boolean);
  const argSummary = extraArgs.length ? ` Key fields: ${extraArgs.join(", ")}.` : "";

  if (component.category === "Custom") {
    return `Reusable custom preset: ${humanizeComponentName(component.name)}.${argSummary}`;
  }
  if (component.category === "Modifiers") {
    return `Modifier wrapper (${describeSlot(component.slotType)}).${argSummary}`;
  }
  if (component.category === "Layout") {
    return `Layout container (${describeSlot(component.slotType)}).${argSummary}`;
  }
  if (component.category === "DrawList") {
    return `DrawList primitive rendered inside NuiDrawList.${argSummary}`;
  }
  if (component.category === "Values") {
    return `Helper value constructor used by other components.${argSummary}`;
  }

  return `${humanizeComponentName(component.name)} (${describeSlot(component.slotType)}).${argSummary}`;
}

function getLexiconUsageNotes(component: NuiComponent): string[] {
  const name = component.name;

  if (name === "NuiWindow") {
    return [
      "Main window shell (title, geometry, and window flags).",
      "It should contain a single root branch (`NuiRoot`).",
      "Keep `jGeometry` as dot-separated floats, e.g. `NuiRect(-1.0, -1.0, 480.0, 320.0)`.",
    ];
  }
  if (name === "NuiRoot") {
    return [
      "Root layout preset exported as `NuiCol` or `NuiRow` based on direction.",
      "Use it as the primary container for the window structure.",
    ];
  }
  if (name === "NuiCol" || name === "NuiRow") {
    return [
      "Core layout container (`NuiCol` = vertical, `NuiRow` = horizontal).",
      "Combine with `NuiSpacer`, `NuiWidth`, and `NuiHeight` for spacing and proportions.",
    ];
  }
  if (name === "NuiGroup") {
    return [
      "Single-child wrapper with optional border and scrollbars.",
      "Useful host for framed sections and `NuiDrawList` content.",
    ];
  }
  if (name === "NuiList") {
    return [
      "Virtualized list driven by template cells and row count.",
      "Most cases should use `NuiListTemplateCell` as `jElements` items.",
      "For dynamic data, initialize and update related binds via `NuiSetBind`.",
    ];
  }
  if (name === "NuiListTemplateCell") {
    return [
      "Defines one list cell template/column.",
      "Use one template for simple rows, or multiple templates for richer layouts.",
    ];
  }
  if (name === "NuiListCell") {
    return [
      "Custom helper for building row/cell content.",
      "Great when you want clearer separation between template logic and field layout.",
    ];
  }
  if (name === "NuiSwapLayout") {
    return [
      "Native anchor for view switching with `NuiSetGroupLayout`.",
      "Treat it as a slot for alternate layouts (view A/B/C).",
    ];
  }
  if (name === "NuiSwap") {
    return [
      "Custom reusable swap-view container preset.",
      "Helps keep multiple view variants structurally consistent.",
    ];
  }
  if (name === "NuiDrawList") {
    return [
      "Host component for draw primitives (`NuiDrawList*`).",
      "Draw items should live inside DrawList, not as regular layout children.",
      "Render order/visibility is controlled by `nOrder` and `nRender`.",
    ];
  }
  if (name.startsWith("NuiDrawList") && name !== "NuiDrawList") {
    return [
      "Primitive rendered by a `NuiDrawList` host.",
      "Keep coordinates and sizes as dot-separated floats to avoid mismatches.",
    ];
  }
  if (name === "NuiComboEntry") {
    return [
      "Value helper, not a layout node.",
      "Use only in entries/sort/page-size arrays for combo/select components.",
    ];
  }

  if (component.category === "Modifiers") {
    return [
      "Wrapper modifier that changes behavior or style of one child.",
      "Apply as close as possible to the target element.",
    ];
  }
  if (component.category === "Values") {
    return [
      "Helper value passed into other components (bind, rect, color, vec, etc.).",
      "Does not render as a standalone UI node.",
    ];
  }
  if (component.category === "Layout") {
    return [
      "Layout component that organizes children by axis/section.",
      "Use with `NuiWidth`/`NuiHeight` wrappers when exact sizing is needed.",
    ];
  }
  if (component.category === "Custom") {
    return [
      "Reusable preset extending base NUI for faster composition.",
      "Treat it as a ready-made building block.",
    ];
  }
  if (component.category === "DrawList") {
    return [
      "Element rendered inside the DrawList pipeline.",
      "When visuals are hidden, verify host setup and draw order first.",
    ];
  }

  return [
    "Base UI component used for layout or interaction.",
    "Check the signature and key fields below for proper setup.",
  ];
}

function getLexiconExtraNotes(component: NuiComponent): string[] {
  const notes: string[] = [
    "Builder tip: double-click a component in the left palette to open its preset properties quickly.",
    "Validation tip: keep numeric geometry and size values as dot-separated floats to avoid export/runtime mismatches.",
  ];

  if (component.args.some((arg) => arg.type.toLowerCase().includes("json"))) {
    notes.push("Bind tip: when you use `NuiBind(...)`, initialize expected values in your `open` event via `NuiSetBind`.");
  }

  if (component.slotType === "single") {
    notes.push("Structure tip: this node accepts exactly one child, so wrap multiple elements with `NuiCol` or `NuiRow`.");
  } else if (component.slotType === "list") {
    notes.push("Structure tip: this node accepts multiple children, so ordering in the children array directly affects layout flow.");
  }

  if (component.name.startsWith("NuiDrawList")) {
    notes.push("Preview tip: verify draw layering both in Visual preview and Aurora runtime when using complex overlays.");
  }

  return notes;
}
