const DEMO_TEMPLATES: PaletteDemoTemplate[] = loadDemoTemplatesFromModules(DEMO_TEMPLATE_JSON_MODULES, LEGACY_DEMO_TEMPLATES);
const DEMO_ASSET_URL_BY_FILE_NAME = loadDemoAssetUrlsFromModules(DEMO_ASSET_MODULES);
const INTEGRATION_TEST_ASSET_URLS_BY_TEST_DIR = loadIntegrationTestAssetUrlsFromModules(INTEGRATION_TEST_ASSET_MODULES);

function isJuiImportObject(value: unknown): value is JuiImportObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function readJuiNumber(value: JuiImportValue | undefined): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && /^-?(?:\d+(?:\.\d+)?|\.\d+)$/.test(value.trim())) {
    const numeric = Number(value.trim());
    return Number.isFinite(numeric) ? numeric : null;
  }
  return null;
}

function parseDemoTemplatePathId(path: string): string {
  const fileName = path.replace(/^.*[\\/]/, "").replace(/\.json$/i, "");
  return fileName || "demo-template";
}

function parseDemoAssetFileName(path: string): string {
  const fileName = path.replace(/^.*[\\/]/, "").trim();
  return fileName.toLowerCase();
}

function loadIntegrationTestAssetUrlsFromModules(modules: Record<string, unknown>): Map<string, IntegrationTestBundledAsset[]> {
  const out = new Map<string, IntegrationTestBundledAsset[]>();
  for (const [path, rawModule] of Object.entries(modules)) {
    if (typeof rawModule !== "string") {
      console.warn(`[test-assets] Skipped '${path}': expected module URL string.`);
      continue;
    }
    const meta = parseIntegrationTestAssetPath(path);
    if (!meta) continue;
    const resref = resRefFromFileName(meta.fileName);
    if (!resref) {
      console.warn(`[test-assets] Skipped '${path}': empty resref after sanitization.`);
      continue;
    }
    const key = meta.testDir.toLowerCase();
    const list = out.get(key) ?? [];
    list.push({
      testDir: meta.testDir,
      fileName: meta.fileName,
      resref,
      url: rawModule,
    });
    out.set(key, list);
  }
  return out;
}

function loadDemoAssetUrlsFromModules(modules: Record<string, unknown>): Map<string, string> {
  const out = new Map<string, string>();
  for (const [path, rawModule] of Object.entries(modules)) {
    if (typeof rawModule !== "string") {
      console.warn(`[demo-assets] Skipped '${path}': expected module URL string.`);
      continue;
    }
    const fileName = parseDemoAssetFileName(path);
    if (!fileName) continue;
    out.set(fileName, rawModule);
  }
  return out;
}

function parseDemoTemplateAssetEntry(rawEntry: unknown, sourcePath: string, index: number): PaletteDemoTemplateAsset | null {
  if (typeof rawEntry === "string") {
    const fileRaw = rawEntry.trim();
    if (!fileRaw) {
      console.warn(`[demo] Skipped '${sourcePath}' assets[${index}]: file name is empty.`);
      return null;
    }
    return { file: fileRaw };
  }

  if (!isJuiImportObject(rawEntry)) {
    console.warn(`[demo] Skipped '${sourcePath}' assets[${index}]: entry must be a string or object.`);
    return null;
  }

  const fileCandidate = typeof rawEntry.file === "string" ? rawEntry.file : typeof rawEntry.path === "string" ? rawEntry.path : "";
  const fileRaw = fileCandidate.trim();
  if (!fileRaw) {
    console.warn(`[demo] Skipped '${sourcePath}' assets[${index}]: missing 'file'.`);
    return null;
  }

  const resrefRaw = typeof rawEntry.resref === "string" ? rawEntry.resref.trim() : "";
  if (resrefRaw) {
    return { file: fileRaw, resref: resrefRaw };
  }
  return { file: fileRaw };
}

function loadDemoTemplatesFromModules(
  modules: Record<string, unknown>,
  fallbackTemplates: PaletteDemoTemplate[],
): PaletteDemoTemplate[] {
  const loadedTemplates: Array<PaletteDemoTemplate & { order: number }> = [];

  for (const [path, rawModule] of Object.entries(modules)) {
    if (!isJuiImportObject(rawModule)) {
      console.warn(`[demo] Skipped '${path}': root JSON value must be an object.`);
      continue;
    }

    const templateIdFromPath = parseDemoTemplatePathId(path);
    const idRaw = typeof rawModule.id === "string" ? rawModule.id.trim() : "";
    const nameRaw = typeof rawModule.name === "string" ? rawModule.name.trim() : "";
    const descriptionRaw = typeof rawModule.description === "string" ? rawModule.description.trim() : "";
    const tagsRaw = Array.isArray(rawModule.tags)
      ? rawModule.tags.filter((value): value is string => typeof value === "string" && value.trim().length > 0).map((value) => value.trim())
      : [];
    const assetsRaw = Array.isArray(rawModule.assets)
      ? rawModule.assets
          .map((entry, index) => parseDemoTemplateAssetEntry(entry, path, index))
          .filter((entry): entry is PaletteDemoTemplateAsset => Boolean(entry))
      : [];
    const juiRaw = rawModule.jui;
    const orderRaw = readJuiNumber(rawModule.order);

    if (!isJuiImportObject(juiRaw)) {
      console.warn(`[demo] Skipped '${path}': \`jui\` must be an object.`);
      continue;
    }

    const validationErrors = validateJuiWindowObject(juiRaw);
    if (validationErrors.length > 0) {
      console.warn(`[demo] '${path}' has non-standard \`jui\`: ${validationErrors.join("; ")}`);
    }

    loadedTemplates.push({
      id: idRaw || templateIdFromPath,
      name: nameRaw || templateIdFromPath,
      description: descriptionRaw,
      tags: tagsRaw,
      assets: assetsRaw,
      jui: juiRaw,
      order: orderRaw === null ? Number.MAX_SAFE_INTEGER : Math.trunc(orderRaw),
    });
  }

  if (loadedTemplates.length === 0) return fallbackTemplates;

  return loadedTemplates
    .sort((a, b) => a.order - b.order || a.name.localeCompare(b.name) || a.id.localeCompare(b.id))
    .map(({ order, ...template }) => template);
}

function parseCustomComponentModelEntry(
  rawEntry: unknown,
  sourcePath: string,
  fallbackOrder: number,
): (CustomComponentModelEntry & { order: number; enabled: boolean; sourcePath: string }) | null {
  if (!isJuiImportObject(rawEntry)) {
    console.warn(`[custom-components] Skipped '${sourcePath}': entry must be an object.`);
    return null;
  }

  const nameRaw = typeof rawEntry.name === "string" ? rawEntry.name.trim() : "";
  if (!nameRaw) {
    console.warn(`[custom-components] Skipped '${sourcePath}': missing non-empty 'name'.`);
    return null;
  }

  const orderRaw = readJuiNumber(rawEntry.order as JuiImportValue);
  const enabledRaw = readJuiBoolean(rawEntry.enabled as JuiImportValue);
  return {
    name: nameRaw,
    order: orderRaw === null ? fallbackOrder : Math.trunc(orderRaw),
    enabled: enabledRaw === null ? true : enabledRaw,
    sourcePath,
  };
}

function loadCustomComponentModels(
  modules: Record<string, unknown>,
): Array<CustomComponentModelEntry & { order: number; enabled: boolean; sourcePath: string }> {
  const loadedEntries: Array<CustomComponentModelEntry & { order: number; enabled: boolean; sourcePath: string }> = [];
  let fallbackOrder = 1000;

  for (const [path, rawModule] of Object.entries(modules)) {
    const parsedSingleEntry = parseCustomComponentModelEntry(rawModule, path, fallbackOrder);
    if (parsedSingleEntry) loadedEntries.push(parsedSingleEntry);
    fallbackOrder += 1;
  }

  return loadedEntries.sort((a, b) => a.order - b.order || a.name.localeCompare(b.name) || a.sourcePath.localeCompare(b.sourcePath));
}

function readJuiBoolean(value: JuiImportValue | undefined): boolean | null {
  if (typeof value === "boolean") return value;
  if (typeof value === "number" && Number.isFinite(value)) return value !== 0;
  if (typeof value === "string") {
    const normalized = value.trim().toUpperCase();
    if (normalized === "TRUE" || normalized === "1") return true;
    if (normalized === "FALSE" || normalized === "0") return false;
  }
  return null;
}

function formatJuiNumeric(value: number): string {
  if (!Number.isFinite(value)) return "0";
  if (Number.isInteger(value)) return String(Math.trunc(value));
  const fixed = value.toFixed(6);
  const trimmed = fixed.replace(/\.?0+$/, "");
  return trimmed || "0";
}

function formatExplicitDotFloat(value: number): string {
  if (!Number.isFinite(value)) return "0.0";
  if (Number.isInteger(value)) return `${Math.trunc(value)}.0`;
  const fixed = value.toFixed(6);
  const trimmed = fixed.replace(/\.?0+$/, "");
  return trimmed.includes(".") ? trimmed : `${trimmed}.0`;
}

function stripUtf8Bom(value: string): string {
  return value.startsWith("\uFEFF") ? value.slice(1) : value;
}

function juiValueToExpression(value: JuiImportValue): string {
  if (value === null) return "JSON_NULL";

  if (typeof value === "boolean") {
    return `JsonBool(${value ? "TRUE" : "FALSE"})`;
  }

  if (typeof value === "number") {
    if (!Number.isFinite(value)) return "JSON_NULL";
    return Number.isInteger(value) ? `JsonInt(${Math.trunc(value)})` : `JsonFloat(${formatJuiNumeric(value)})`;
  }

  if (typeof value === "string") {
    return `JsonString("${escapeNwString(value)}")`;
  }

  if (Array.isArray(value)) {
    return value.reduce<string>((expr, item) => `JsonArrayInsert(${expr}, ${juiValueToExpression(item)})`, "JsonArray()");
  }

  if (isJuiImportObject(value)) {
    if (typeof value.bind === "string") {
      const numberFlags = readJuiNumber(value.number_flags) ?? 0;
      const numberPrecision = readJuiNumber(value.number_precision) ?? 0;
      const textFlags = readJuiNumber(value.text_flags) ?? 0;
      const nFlags = Math.trunc(numberFlags);
      const nPrecision = Math.trunc(numberPrecision);
      const nTextFlags = Math.trunc(textFlags);
      if (nFlags === 0 && nPrecision === 0 && nTextFlags === 0) {
        return `NuiBind("${escapeNwString(value.bind)}")`;
      }
      return `NuiBind("${escapeNwString(value.bind)}", ${nFlags}, ${nPrecision}, ${nTextFlags})`;
    }

    const strRef = readJuiNumber(value.strref);
    if (strRef !== null) {
      return `NuiStrRef(${Math.trunc(strRef)})`;
    }

    const vecX = readJuiNumber(value.x);
    const vecY = readJuiNumber(value.y);
    const rectW = readJuiNumber(value.w);
    const rectH = readJuiNumber(value.h);
    if (vecX !== null && vecY !== null && rectW !== null && rectH !== null) {
      return `NuiRect(${formatExplicitDotFloat(vecX)}, ${formatExplicitDotFloat(vecY)}, ${formatExplicitDotFloat(rectW)}, ${formatExplicitDotFloat(rectH)})`;
    }
    if (vecX !== null && vecY !== null) {
      return `NuiVec(${formatExplicitDotFloat(vecX)}, ${formatExplicitDotFloat(vecY)})`;
    }

    const colorR = readJuiNumber(value.r);
    const colorG = readJuiNumber(value.g);
    const colorB = readJuiNumber(value.b);
    if (colorR !== null && colorG !== null && colorB !== null) {
      const colorA = readJuiNumber(value.a);
      if (colorA === null || Math.trunc(colorA) === 255) {
        return `NuiColor(${Math.trunc(colorR)}, ${Math.trunc(colorG)}, ${Math.trunc(colorB)})`;
      }
      return `NuiColor(${Math.trunc(colorR)}, ${Math.trunc(colorG)}, ${Math.trunc(colorB)}, ${Math.trunc(colorA)})`;
    }

    let objectExpr = "JsonObject()";
    for (const [key, item] of Object.entries(value)) {
      objectExpr = `JsonObjectSet(${objectExpr}, JsonString("${escapeNwString(key)}"), ${juiValueToExpression(item)})`;
    }
    return objectExpr;
  }

  return "JSON_NULL";
}

function validateJuiWindowObject(raw: Record<string, unknown>): string[] {
  const errors: string[] = [];
  for (const key of JUI_REQUIRED_WINDOW_KEYS) {
    if (!(key in raw)) {
      errors.push(`missing \`${key}\``);
    }
  }

  if ("version" in raw) {
    const version = readJuiNumber(raw.version as JuiImportValue);
    if (version === null || Math.trunc(version) !== 1) {
      errors.push("`version` must be numeric value 1");
    }
  }

  if ("root" in raw) {
    if (!isJuiImportObject(raw.root)) {
      errors.push("`root` must be an object");
    } else {
      const rootType = raw.root.type;
      if (typeof rootType !== "string" || !rootType.trim()) {
        errors.push("`root.type` must be a non-empty string");
      }
    }
  }

  if ("geometry" in raw) {
    if (!isJuiImportObject(raw.geometry)) {
      errors.push("`geometry` must be an object");
    } else {
      const geometry = raw.geometry;
      const geometryBindId = typeof geometry.bind === "string" ? geometry.bind.trim() : "";
      if (geometryBindId) {
        if ("number_flags" in geometry && readJuiNumber(geometry.number_flags) === null) {
          errors.push("`geometry.number_flags` must be numeric");
        }
        if ("number_precision" in geometry && readJuiNumber(geometry.number_precision) === null) {
          errors.push("`geometry.number_precision` must be numeric");
        }
        if ("text_flags" in geometry && readJuiNumber(geometry.text_flags) === null) {
          errors.push("`geometry.text_flags` must be numeric");
        }
      } else {
        const axes = ["x", "y", "w", "h"] as const;
        const axisValues: Partial<Record<typeof axes[number], number>> = {};
        for (const axis of axes) {
          const numericValue = readJuiNumber(geometry[axis]);
          if (numericValue === null) {
            errors.push(`\`geometry.${axis}\` must be numeric`);
          } else {
            axisValues[axis] = numericValue;
          }
        }
        if (axisValues.w !== undefined && axisValues.w <= 0) {
          errors.push("`geometry.w` must be > 0");
        }
        if (axisValues.h !== undefined && axisValues.h <= 0) {
          errors.push("`geometry.h` must be > 0");
        }
      }
    }
  }

  return errors;
}

function splitPathSegments(path: string): string[] {
  return path.split("/").filter(Boolean);
}

function collectIntegrationTestImageResrefs(root: Record<string, unknown>): string[] {
  const out = new Set<string>();
  const visit = (value: unknown): void => {
    if (Array.isArray(value)) {
      for (const item of value) visit(item);
      return;
    }
    if (!isJuiImportObject(value)) return;

    const rawType = value.type;
    if (typeof rawType === "string") {
      const typeToken = rawType.trim().toLowerCase();
      if (typeToken === "image") {
        const imageResref = normalizeResRef(typeof value.value === "string" ? value.value : "");
        if (imageResref) out.add(imageResref);
      } else if (typeToken === "button_image") {
        // In imported .jui, button_image resref is stored in `label`.
        const buttonImageResref = normalizeResRef(typeof value.label === "string" ? value.label : "");
        if (buttonImageResref) out.add(buttonImageResref);
      }
    } else {
      const drawType = readJuiNumber(rawType);
      if (drawType === 5) {
        const drawImageResref = normalizeResRef(typeof value.image === "string" ? value.image : "");
        if (drawImageResref) out.add(drawImageResref);
      }
    }

    for (const nested of Object.values(value)) {
      visit(nested);
    }
  };

  visit(root);
  return [...out];
}

function parseIntegrationTestRelativeSegments(path: string): string[] {
  const normalized = path.replace(/\\/g, "/");
  const segments = splitPathSegments(normalized);
  const testsIndex = segments.findIndex((segment) => segment.toLowerCase() === "tests");
  if (testsIndex >= 0) {
    return segments.slice(testsIndex + 1);
  }
  return segments;
}

function isIntegrationTestPathAllowed(path: string): boolean {
  const relativeSegments = parseIntegrationTestRelativeSegments(path).map((segment) => segment.toLowerCase());
  if (relativeSegments.length < 2) return false;
  const rootDir = relativeSegments[0];
  if (rootDir !== "app" && rootDir !== "integration_tests") return false;
  if (relativeSegments.some((segment) => segment.startsWith("_"))) return false;
  const blocked = new Set(["archive", "artifacts", "api_runner", "menu", "jui_export", "script_export"]);
  if (relativeSegments.some((segment) => blocked.has(segment))) return false;
  return true;
}

function parseIntegrationTestRelativeDir(relativePath: string): string {
  const normalized = relativePath.replace(/\\/g, "/").trim();
  if (!normalized) return "";
  const segments = splitPathSegments(normalized);
  if (segments.length <= 1) return "";
  return segments.slice(0, -1).join("/");
}

function parseIntegrationTestPath(path: string): { name: string; fileName: string; folderName: string; relativePath: string } {
  const relativeSegments = parseIntegrationTestRelativeSegments(path);
  const fileName = relativeSegments[relativeSegments.length - 1] || "";
  const folderName = relativeSegments.length > 1 ? relativeSegments[relativeSegments.length - 2] : "";
  const name = fileName.replace(/\.jui$/i, "") || folderName || "test";
  return {
    name,
    fileName,
    folderName: folderName || name,
    relativePath: relativeSegments.join("/"),
  };
}

function parseIntegrationTestAssetPath(path: string): { testDir: string; fileName: string } | null {
  if (!isIntegrationTestPathAllowed(path)) return null;
  const relativeSegments = parseIntegrationTestRelativeSegments(path);
  if (!relativeSegments.length) return null;
  const lowerSegments = relativeSegments.map((segment) => segment.toLowerCase());
  const assetsIndex = lowerSegments.lastIndexOf("assets");
  if (assetsIndex <= 0 || assetsIndex >= relativeSegments.length - 1) return null;
  const testDir = relativeSegments.slice(0, assetsIndex).join("/");
  const fileName = relativeSegments[relativeSegments.length - 1] || "";
  if (!testDir || !fileName) return null;
  return { testDir, fileName };
}

function createDefaultRootContainerNode(id: string): NuiNode {
  return {
    id,
    componentName: CUSTOM_ROOT_COMPONENT,
    props: { nDirection: NUI_ROOT_DIRECTION_COL },
    children: [],
  };
}

function createWindowRootNode(id: string, children?: NuiNode[]): NuiNode {
  const normalizedChildren = children && children.length ? children : [createDefaultRootContainerNode(`${id}_root`)];
  return {
    id,
    componentName: "NuiWindow",
    props: { ...DEFAULT_WINDOW_PROPS },
    children: normalizedChildren,
  };
}

function normalizeRootIntoWindow(root: NuiNode[]): NuiNode[] {
  if (!root.length) {
    return [createWindowRootNode(`node_import_${Math.random().toString(36).slice(2, 10)}`)];
  }

  const firstWindowIndex = root.findIndex((node) => node.componentName === "NuiWindow");
  if (firstWindowIndex === -1) {
    return [createWindowRootNode(`node_import_${Math.random().toString(36).slice(2, 10)}`, root)];
  }

  const windowNode = root[firstWindowIndex];
  const siblings = root.filter((_, idx) => idx !== firstWindowIndex);
  if (siblings.length) {
    windowNode.children = [...windowNode.children, ...siblings];
  }
  if (!windowNode.children.length) {
    windowNode.children = [createDefaultRootContainerNode(`${windowNode.id}_root`)];
  }

  return [windowNode];
}

function cloneNode(node: NuiNode): NuiNode {
  return {
    id: node.id,
    componentName: node.componentName,
    props: { ...node.props },
    children: node.children.map(cloneNode),
  };
}

function cloneForest(nodes: NuiNode[]): NuiNode[] {
  return nodes.map(cloneNode);
}

function clonePresetsMap(presets: Record<string, Record<string, string>>): Record<string, Record<string, string>> {
  const out: Record<string, Record<string, string>> = {};
  for (const [componentName, values] of Object.entries(presets)) {
    out[componentName] = { ...values };
  }
  return out;
}

function findNodeById(nodes: NuiNode[], nodeId: string, path: number[] = []): NodePathHit | null {
  for (let idx = 0; idx < nodes.length; idx += 1) {
    const node = nodes[idx];
    const currentPath = [...path, idx];
    if (node.id === nodeId) return { node, path: currentPath };
    const childHit = findNodeById(node.children, nodeId, currentPath);
    if (childHit) return childHit;
  }
  return null;
}

function getParentArrayByPath(forest: NuiNode[], path: number[]): NuiNode[] {
  if (path.length <= 1) return forest;
  const parentPath = path.slice(0, -1);
  let current = forest;
  for (const index of parentPath) {
    current = current[index].children;
  }
  return current;
}

function getNodeByPath(forest: NuiNode[], path: number[]): NuiNode | null {
  if (!path.length) return null;
  let current = forest;
  let node: NuiNode | null = null;
  for (const index of path) {
    if (index < 0 || index >= current.length) return null;
    node = current[index];
    current = node.children;
  }
  return node;
}

function containsNodeId(node: NuiNode, maybeChildId: string): boolean {
  for (const child of node.children) {
    if (child.id === maybeChildId) return true;
    if (containsNodeId(child, maybeChildId)) return true;
  }
  return false;
}

function normalizeResRef(value: string): string {
  return value.trim().toLowerCase();
}

function sanitizeResRef(value: string): string {
  return normalizeResRef(value)
    .replace(/[^a-z0-9_]/g, "_")
    .replace(/^_+|_+$/g, "");
}

function resRefFromFileName(fileName: string): string {
  const base = fileName.includes(".") ? fileName.slice(0, fileName.lastIndexOf(".")) : fileName;
  return sanitizeResRef(base);
}

function extensionFromFileName(fileName: string): string {
  return fileName.includes(".") ? (fileName.split(".").pop() || "").toLowerCase().trim() : "";
}

function parseAssetFile(file: File): ParsedAssetFileResult {
  const ext = extensionFromFileName(file.name);
  const baseName = file.name.includes(".") ? file.name.slice(0, file.name.lastIndexOf(".")) : file.name;
  const resref = resRefFromFileName(file.name);
  const issues: string[] = [];

  if (!SUPPORTED_IMAGE_EXTENSIONS.has(ext)) {
    issues.push(`${file.name}: unsupported extension .${ext || "?"} (allowed: ${[...SUPPORTED_IMAGE_EXTENSIONS].join(", ")})`);
  }
  if (baseName.length > MAX_RESREF_LENGTH) {
    issues.push(`${file.name}: base file name exceeds ${MAX_RESREF_LENGTH} chars`);
  }
  if (!resref) {
    issues.push(`${file.name}: resref is empty after sanitization`);
  } else if (resref.length > MAX_RESREF_LENGTH) {
    issues.push(`${file.name}: resref exceeds ${MAX_RESREF_LENGTH} chars`);
  }

  if (issues.length) {
    return { asset: null, issues };
  }

  const asset: NuiAsset = {
    name: file.name,
    resref,
    ext,
    mimeType: file.type || "",
    previewUrl: createAssetPreviewUrl(file, ext),
    sourceFile: file,
    size: file.size,
    supported: true,
  };
  return { asset, issues: [] };
}

function extractResRefValue(raw: string | undefined): string {
  const v = String(raw ?? "").trim();
  const jsonMatch = v.match(/^JsonString\("(.*)"\)$/);
  if (jsonMatch) return jsonMatch[1];
  const quoteMatch = v.match(/^"(.*)"$/);
  if (quoteMatch) return quoteMatch[1];
  return v;
}

function toJsonStringLiteral(value: string): string {
  const escaped = value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  return `JsonString("${escaped}")`;
}

function getBundledSkinPreviewUrl(resref: string): string | null {
  const key = normalizeResRef(resref);
  const ext = NUI_BUNDLED_SKIN_EXT_BY_RESREF[key];
  if (!ext) return null;
  return `${NUI_SKIN_PREVIEW_ROOT}/${key}.${ext}`;
}

function getSkinPreviewUrl(resref: string, assetByResRef: Map<string, NuiAsset>): { url: string | null; isVideo: boolean } {
  const key = normalizeResRef(resref);
  const asset = assetByResRef.get(key);
  if (asset?.previewUrl) {
    return {
      url: asset.previewUrl,
      isVideo: asset.ext === "webm" || asset.ext === "wbm",
    };
  }
  return { url: getBundledSkinPreviewUrl(key), isVideo: false };
}

function createAssetPreviewUrl(file: File, ext: string): string | null {
  if (!PREVIEWABLE_IMAGE_EXTENSIONS.has(ext)) return null;
  try {
    return URL.createObjectURL(file);
  } catch {
    return null;
  }
}

function triggerBlobDownload(fileName: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}

function countImportIssueItems(message: string): number {
  const lines = message.split(/\r?\n/);
  const bulletCount = lines.filter((line) => line.trimStart().startsWith("- ")).length;
  if (bulletCount > 0) return bulletCount;
  if (message.trim().length === 0) return 0;
  return 1;
}

function formatImportFailureNotice(message: string): string {
  const issueCount = countImportIssueItems(message);
  if (issueCount >= CRITICAL_IMPORT_ERROR_MIN_ITEMS) {
    return `KRYTYCZNY BĹÄ„D IMPORTU (${issueCount})\n${message}\n\nImport przerwany. Popraw plik i sprĂłbuj ponownie.`;
  }
  return message;
}

function buildValidationReportText(project: NuiProjectMeta, errors: string[], warnings: string[]): string {
  const lines: string[] = [];
  lines.push("NUI Builder - Validation Report");
  lines.push(`Generated: ${new Date().toISOString()}`);
  lines.push(`Project: ${project.name.trim() || "nui_project"}`);
  lines.push(`Window ID: ${project.windowId.trim() || "NUI_WINDOW"}`);
  lines.push(`Event Script: ${project.eventScript.trim() || "nui_window_ev"}`);
  lines.push("");
  lines.push(`Errors: ${errors.length}`);
  if (errors.length) {
    errors.forEach((error, index) => lines.push(`${index + 1}. ${error}`));
  } else {
    lines.push("None.");
  }
  lines.push("");
  lines.push(`Warnings: ${warnings.length}`);
  if (warnings.length) {
    warnings.forEach((warning, index) => lines.push(`${index + 1}. ${warning}`));
  } else {
    lines.push("None.");
  }
  return lines.join("\n");
}

function encodeHakV10(entries: HakResourceEntry[]): Blob {
  const headerSize = 160;
  const keyEntrySize = 24;
  const resourceEntrySize = 8;
  const keyTableSize = entries.length * keyEntrySize;
  const resourceTableSize = entries.length * resourceEntrySize;
  const dataSize = entries.reduce((sum, entry) => sum + entry.bytes.byteLength, 0);
  const buffer = new ArrayBuffer(headerSize + keyTableSize + resourceTableSize + dataSize);
  const view = new DataView(buffer);
  const bytes = new Uint8Array(buffer);
  const encoder = new TextEncoder();

  const writeFixedAscii = (offset: number, value: string, length: number): void => {
    const encoded = encoder.encode(value);
    const count = Math.min(length, encoded.length);
    bytes.set(encoded.subarray(0, count), offset);
    for (let idx = count; idx < length; idx += 1) {
      bytes[offset + idx] = 0;
    }
  };

  writeFixedAscii(0, "HAK ", 4);
  writeFixedAscii(4, "V1.0", 4);

  const keyOffset = headerSize;
  const resourceOffset = keyOffset + keyTableSize;
  const dataOffsetStart = resourceOffset + resourceTableSize;
  const now = new Date();
  const startOfYear = new Date(now.getFullYear(), 0, 1);
  const dayOfYear = Math.floor((now.getTime() - startOfYear.getTime()) / 86400000);

  view.setUint32(8, 0, true); // localizedstrings_count
  view.setUint32(12, 0, true); // localizedstrings_size
  view.setUint32(16, entries.length, true); // keys_count
  view.setUint32(20, headerSize, true); // localizedstrings_offset
  view.setUint32(24, keyOffset, true); // keys_offset
  view.setUint32(28, resourceOffset, true); // resources_offset
  view.setUint32(32, now.getFullYear() - 1900, true); // build_year
  view.setUint32(36, dayOfYear, true); // build_day
  view.setUint32(40, 0, true); // file_description_strref

  let dataOffset = dataOffsetStart;
  entries.forEach((entry, index) => {
    const keyEntryOffset = keyOffset + index * keyEntrySize;
    writeFixedAscii(keyEntryOffset, entry.resref, 16);
    view.setUint32(keyEntryOffset + 16, index, true);
    view.setUint16(keyEntryOffset + 20, entry.resourceType, true);
    view.setUint16(keyEntryOffset + 22, 0, true);

    const resourceEntryOffset = resourceOffset + index * resourceEntrySize;
    view.setUint32(resourceEntryOffset, dataOffset, true);
    view.setUint32(resourceEntryOffset + 4, entry.bytes.byteLength, true);
    bytes.set(entry.bytes, dataOffset);
    dataOffset += entry.bytes.byteLength;
  });

  return new Blob([buffer], { type: "application/octet-stream" });
}

function isNwIdentifier(value: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(value);
}

