function parsePlainBool(value: string): boolean | null {
  const v = value.trim().toUpperCase();
  if (v === "TRUE" || v === "1") return true;
  if (v === "FALSE" || v === "0") return false;
  return null;
}

function parseBoolKeyword(value: string): boolean | null {
  const v = value.trim().toUpperCase();
  if (v === "TRUE") return true;
  if (v === "FALSE") return false;
  return null;
}

function parseJsonBool(value: string): boolean | null {
  const match = value.trim().match(/^JsonBool\((TRUE|FALSE)\)$/i);
  if (!match) return null;
  return match[1].toUpperCase() === "TRUE";
}

function isIntToken(value: string): boolean {
  return /^-?\d+$/.test(value.trim());
}

function isFloatToken(value: string): boolean {
  return /^-?\d+(\.\d+)?$/.test(value.trim());
}

function isDotFloatToken(value: string): boolean {
  return /^-?\d+\.\d+$/.test(value.trim());
}

function isBooleanIntArg(arg: NuiArg): boolean {
  return /^b[A-Z0-9_]/.test(arg.name);
}

function getEnumSpec(componentName: string, arg: NuiArg): NuiEnumSpec | null {
  if (arg.type === "int") {
    if (
      arg.name === "nDirection" &&
      (componentName === CUSTOM_ROOT_COMPONENT || componentName === CUSTOM_SWAP_VIEW_COMPONENT || componentName === CUSTOM_LIST_CELL_COMPONENT)
    ) {
      return { kind: "int", options: NUI_ROOT_DIRECTION_OPTIONS };
    }
    if (arg.name === "nDirection") return { kind: "int", options: NUI_DIRECTION_OPTIONS };
    if (arg.name === "nScroll") {
      return { kind: "int", options: NUI_SCROLL_OPTIONS };
    }
    if (arg.name === "nType" && componentName === "NuiChartSlot") return { kind: "int", options: NUI_CHART_TYPE_OPTIONS };
    if (arg.name === "nOrder") return { kind: "int", options: NUI_DRAW_ORDER_OPTIONS };
    if (arg.name === "nRender") return { kind: "int", options: NUI_DRAW_RENDER_OPTIONS };
  }
  if (arg.type === "json") {
    if (arg.name === "jHAlign") return { kind: "json-int", options: NUI_HALIGN_OPTIONS };
    if (arg.name === "jVAlign") return { kind: "json-int", options: NUI_VALIGN_OPTIONS };
    if (arg.name === "jAspect") return { kind: "json-int", options: NUI_ASPECT_OPTIONS };
  }
  return null;
}

function enumTokenByNumericValue(spec: NuiEnumSpec, numeric: number): string | null {
  const found = spec.options.find((option) => option.value === numeric);
  return found ? found.token : null;
}

function resolveEnumToken(componentName: string, arg: NuiArg, raw: string): string | null {
  const spec = getEnumSpec(componentName, arg);
  if (!spec) return null;

  const value = raw.trim();
  if (!value) return null;

  if (spec.options.some((option) => option.token === value)) {
    return value;
  }

  if (spec.kind === "json-int") {
    const jsonInt = value.match(/^JsonInt\(([^)]+)\)$/i);
    if (jsonInt) {
      const inner = jsonInt[1].trim();
      if (spec.options.some((option) => option.token === inner)) {
        return inner;
      }
      if (isIntToken(inner)) {
        return enumTokenByNumericValue(spec, Number(inner));
      }
      return null;
    }
  }

  if (isIntToken(value)) {
    return enumTokenByNumericValue(spec, Number(value));
  }

  return null;
}

function enumOptionsForArg(componentName: string, arg: NuiArg): string[] {
  const spec = getEnumSpec(componentName, arg);
  return spec ? spec.options.map((option) => option.token) : [];
}

function inferPropertyInputKind(componentName: string, arg: NuiArg, currentValue: string, fallbackValue: string): PropertyInputKind {
  const current = currentValue.trim();
  const fallback = fallbackValue.trim();
  const probe = current || fallback;
  const enumSpec = getEnumSpec(componentName, arg);

  if (enumSpec?.kind === "int") return "enum-int";
  if (enumSpec?.kind === "json-int") return "enum-json-int";

  if (arg.type === "json") {
    if (componentName === "NuiButtonSelect" && arg.name === "jValue") {
      return isNuiBindToken(probe) ? "text" : "bool-json";
    }
    if (isVecJsonArg(componentName, arg.name)) return "vec-json";
    if (isRectJsonArg(componentName, arg.name)) return "rect-json";
    return parseJsonBool(probe) !== null ? "bool-json" : "text";
  }

  if (arg.type === "int") {
    if (isBooleanIntArg(arg) && parsePlainBool(probe) !== null) return "bool-int";
    if (parseBoolKeyword(probe) !== null) return "bool-int";
    if (isIntToken(probe)) return "int";
    return "text";
  }

  if (arg.type === "float") {
    if (isFloatToken(probe)) return "float";
    return "text";
  }

  return "text";
}

function hasBalancedParentheses(value: string): boolean {
  let depth = 0;
  for (const char of value) {
    if (char === "(") depth += 1;
    if (char === ")") {
      depth -= 1;
      if (depth < 0) return false;
    }
  }
  return depth === 0;
}

function hasBalancedQuotes(value: string): boolean {
  let doubleQuoteOpen = false;
  for (let i = 0; i < value.length; i += 1) {
    if (value[i] !== '"') continue;
    const escaped = i > 0 && value[i - 1] === "\\";
    if (!escaped) {
      doubleQuoteOpen = !doubleQuoteOpen;
    }
  }
  return !doubleQuoteOpen;
}

function splitTopLevelArgs(input: string): string[] {
  const args: string[] = [];
  let current = "";
  let depth = 0;
  let inDoubleQuote = false;

  for (let i = 0; i < input.length; i += 1) {
    const char = input[i];
    const prev = i > 0 ? input[i - 1] : "";
    if (char === '"' && prev !== "\\") {
      inDoubleQuote = !inDoubleQuote;
      current += char;
      continue;
    }
    if (!inDoubleQuote) {
      if (char === "(") depth += 1;
      if (char === ")") depth = Math.max(0, depth - 1);
      if (char === "," && depth === 0) {
        args.push(current.trim());
        current = "";
        continue;
      }
    }
    current += char;
  }
  if (current.trim()) args.push(current.trim());
  return args;
}

function parseFunctionCallArgs(raw: string, functionName: string): string[] | null {
  const value = raw.trim();
  const prefix = `${functionName}(`;
  if (!value.startsWith(prefix) || !value.endsWith(")")) return null;
  const inner = value.slice(prefix.length, -1);
  if (!hasBalancedParentheses(inner) || !hasBalancedQuotes(inner)) return null;
  return splitTopLevelArgs(inner);
}

function parseQuotedOrJsonString(raw: string): string | null {
  const value = raw.trim();
  const quoted = value.match(/^"((?:\\.|[^"\\])*)"$/);
  if (quoted) return unescapeNwString(quoted[1]);

  const jsonString = value.match(/^JsonString\("((?:\\.|[^"\\])*)"\)$/i);
  if (jsonString) return unescapeNwString(jsonString[1]);

  return null;
}

function parseJsonIntLiteral(raw: string): number | null {
  const value = raw.trim();
  if (isIntToken(value)) return Number(value);
  const jsonInt = value.match(/^JsonInt\(\s*(-?\d+)\s*\)$/i);
  if (jsonInt) return Number(jsonInt[1]);
  return null;
}

function isConstantToken(value: string): boolean {
  return /^[A-Z_][A-Z0-9_]*$/.test(value.trim());
}

function isJsonIntCompatibleExpression(raw: string): boolean {
  const value = raw.trim();
  if (!value) return false;
  if (isIntToken(value) || isConstantToken(value)) return true;
  const jsonInt = value.match(/^JsonInt\((.*)\)$/i);
  if (!jsonInt) return false;
  const inner = jsonInt[1].trim();
  return isIntToken(inner) || isConstantToken(inner);
}

function isJsonNumberCompatibleExpression(raw: string): boolean {
  const value = raw.trim();
  if (!value) return false;
  if (isFloatToken(value) || isConstantToken(value)) return true;
  const jsonInt = value.match(/^JsonInt\((.*)\)$/i);
  if (jsonInt) {
    const inner = jsonInt[1].trim();
    return isIntToken(inner) || isConstantToken(inner);
  }
  const jsonFloat = value.match(/^JsonFloat\((.*)\)$/i);
  if (jsonFloat) {
    const inner = jsonFloat[1].trim();
    return isFloatToken(inner) || isConstantToken(inner);
  }
  return false;
}

function isBoolIntCompatibleExpression(raw: string): boolean {
  const value = raw.trim();
  if (!value) return false;
  if (parsePlainBool(value) !== null) return true;
  if (isIntToken(value)) {
    const numeric = Number(value);
    return numeric === 0 || numeric === 1;
  }
  return isConstantToken(value);
}

function parseJsonNumberLiteral(raw: string): number | null {
  const value = raw.trim();
  if (!value) return null;
  if (isFloatToken(value)) return Number(value);
  const jsonInt = value.match(/^JsonInt\(\s*(-?\d+)\s*\)$/i);
  if (jsonInt) return Number(jsonInt[1]);
  const jsonFloat = value.match(/^JsonFloat\(\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*\)$/i);
  if (jsonFloat) return Number(jsonFloat[1]);
  return null;
}

function parseJsonArrayInsertItems(raw: string): string[] | null {
  const items: string[] = [];
  let cursor = raw.trim();

  while (true) {
    if (/^JsonArray\(\)$/i.test(cursor)) {
      return items.reverse();
    }
    const args = parseFunctionCallArgs(cursor, "JsonArrayInsert");
    if (!args || args.length !== 2) return null;
    items.push(args[1]);
    cursor = args[0].trim();
  }
}

function parseComboEntryLiteral(raw: string): ComboPreviewEntry | null {
  const value = raw.trim();
  const comboArgs = parseFunctionCallArgs(value, "NuiComboEntry");
  if (comboArgs && comboArgs.length === 2) {
    const label = parseQuotedOrJsonString(comboArgs[0]);
    const entryValue = parseJsonIntLiteral(comboArgs[1]);
    if (label === null || entryValue === null) return null;
    return { label, value: entryValue };
  }

  const tupleArgs = parseFunctionCallArgs(value, "JsonArrayInsert");
  if (!tupleArgs || tupleArgs.length !== 2) return null;
  const tupleBaseArgs = parseFunctionCallArgs(tupleArgs[0], "JsonArrayInsert");
  if (!tupleBaseArgs || tupleBaseArgs.length !== 2 || !/^JsonArray\(\)$/i.test(tupleBaseArgs[0].trim())) return null;

  const label = parseQuotedOrJsonString(tupleBaseArgs[1]);
  const entryValue = parseJsonIntLiteral(tupleArgs[1]);
  if (label === null || entryValue === null) return null;
  return { label, value: entryValue };
}

function tryParseComboEntries(raw: string | undefined): ComboPreviewEntry[] | null {
  const value = String(raw ?? "").trim();
  if (!value || value === "JSON_NULL" || isNuiBindToken(value)) return null;
  if (/^JsonArray\(\)$/i.test(value)) return [];

  const directEntries = [...value.matchAll(/NuiComboEntry\("((?:\\.|[^"\\])*)"\s*,\s*(-?\d+)\s*\)/g)].map((match) => ({
    label: unescapeNwString(match[1]),
    value: Number(match[2]),
  }));
  if (directEntries.length) return directEntries;

  const items = parseJsonArrayInsertItems(value);
  if (!items) return null;
  const parsed = items.map((item) => parseComboEntryLiteral(item));
  if (parsed.some((entry) => entry === null)) return null;
  return parsed as ComboPreviewEntry[];
}

function sanitizeComboEntries(entries: ComboPreviewEntry[]): ComboPreviewEntry[] {
  return entries
    .map((entry) => ({
      label: entry.label.trim(),
      value: Math.trunc(Number.isFinite(entry.value) ? entry.value : 0),
    }))
    .filter((entry) => entry.label.length > 0);
}

function buildComboElementsValue(entries: ComboPreviewEntry[]): string {
  const clean = sanitizeComboEntries(entries);
  if (!clean.length) return "JsonArray()";
  return clean.reduce(
    (expr, entry) => `JsonArrayInsert(${expr}, NuiComboEntry("${escapeNwString(entry.label)}", ${entry.value}))`,
    "JsonArray()",
  );
}

function parseNuiBindDescriptor(raw: string | undefined): ParsedNuiBindDescriptor | null {
  const value = String(raw ?? "").trim();
  const match = value.match(/^NuiBind\((.*)\)$/);
  if (!match) return null;
  const parts = splitTopLevelArgs(match[1]);
  if (parts.length < 1 || parts.length > 4) return null;
  const idRaw = parts[0]?.trim() ?? "";
  const idMatch = idRaw.match(/^"((?:\\.|[^"\\])*)"$/);
  if (!idMatch) return null;
  return {
    id: unescapeNwString(idMatch[1]),
    numberFlags: parts[1]?.trim() || "0",
    numberPrecision: parts[2]?.trim() || "0",
    textFlags: parts[3]?.trim() || "0",
  };
}

function buildNuiBindExpression(bind: ParsedNuiBindDescriptor): string {
  const id = escapeNwString(bind.id.trim() || "bind");
  const numberFlags = bind.numberFlags.trim() || "0";
  const numberPrecision = bind.numberPrecision.trim() || "0";
  const textFlags = bind.textFlags.trim() || "0";
  if (numberFlags === "0" && numberPrecision === "0" && textFlags === "0") {
    return `NuiBind("${id}")`;
  }
  return `NuiBind("${id}", ${numberFlags}, ${numberPrecision}, ${textFlags})`;
}

function parseBitmaskExpression(raw: string, constants: Record<string, number>): number | null {
  const value = raw.trim();
  if (!value) return 0;
  const parts = value
    .split("|")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  if (!parts.length) return 0;

  let mask = 0;
  for (const part of parts) {
    if (isIntToken(part)) {
      mask |= Number(part);
      continue;
    }
    const token = part.replace(/^\(+/, "").replace(/\)+$/, "");
    if (!(token in constants)) return null;
    mask |= constants[token];
  }
  return mask;
}

function applyBindTextFlags(value: string, textFlagsExpr: string): string {
  const mask = parseBitmaskExpression(textFlagsExpr, {
    NUI_TEXT_FLAG_LOWERCASE,
    NUI_TEXT_FLAG_UPPERCASE,
  });
  if (mask === null) return value;
  const hasLower = (mask & NUI_TEXT_FLAG_LOWERCASE) !== 0;
  const hasUpper = (mask & NUI_TEXT_FLAG_UPPERCASE) !== 0;
  if (hasLower && hasUpper) return value;
  if (hasUpper) return value.toUpperCase();
  if (hasLower) return value.toLowerCase();
  return value;
}

function parseNuiStrRefToken(raw: string | undefined): number | null {
  const value = String(raw ?? "").trim();
  if (!value) return null;

  const callMatch = value.match(/^NuiStrRef\(\s*(-?\d+)\s*\)$/i);
  if (callMatch) return Number(callMatch[1]);

  const objectMatch = value.match(/^\{\s*"strref"\s*:\s*(-?\d+)\s*\}$/i);
  if (objectMatch) return Number(objectMatch[1]);

  return null;
}

function isStringLikeJsonArg(componentName: string, argName: string): boolean {
  return STRING_LIKE_JSON_ARGS.has(`${componentName}.${argName}`);
}

function isVecJsonArg(componentName: string, argName: string): boolean {
  return VEC2_JSON_ARGS.has(`${componentName}.${argName}`);
}

function isRectJsonArg(componentName: string, argName: string): boolean {
  return RECT_JSON_ARGS.has(`${componentName}.${argName}`);
}

function validateExpressionValue(componentName: string, arg: NuiArg, value: string): string | null {
  const v = value.trim();
  if (!v) return null;

  if (componentName === "NuiId" && arg.name === "sId") {
    if (!parseNuiIdValue(v)) {
      return "NuiId.sId cannot be empty.";
    }
    return null;
  }

  if (!hasBalancedQuotes(v)) {
    return "Unbalanced double quotes.";
  }
  if (!hasBalancedParentheses(v)) {
    return "Unbalanced parentheses.";
  }

  const enumSpec = getEnumSpec(componentName, arg);
  if (enumSpec) {
    const token = resolveEnumToken(componentName, arg, v);
    if (token) return null;
    if (enumSpec.kind === "json-int" && isNuiBindToken(v)) return null;
    const expected = enumOptionsForArg(componentName, arg).join(", ");
    if (enumSpec.kind === "json-int") {
      return `Expected JsonInt(<constant>) or NuiBind(). Allowed: ${expected}.`;
    }
    return `Expected one of: ${expected}.`;
  }

  if (arg.type === "json" && isStringLikeJsonArg(componentName, arg.name)) {
    if (/^NuiStrRef\(/i.test(v)) {
      if (parseNuiStrRefToken(v) === null) {
        return "Expected NuiStrRef(<int>).";
      }
      return null;
    }
    if (/^\{/.test(v) && /"strref"/i.test(v)) {
      if (parseNuiStrRefToken(v) === null) {
        return 'Expected {"strref": <int>} for strref object payload.';
      }
      return null;
    }
  }

  if (componentName === "NuiButtonSelect" && arg.name === "jValue") {
    if (isNuiBindToken(v)) return null;
    if (parseJsonBool(v) !== null) return null;
    return "Expected JsonBool(TRUE/FALSE) or NuiBind(...) for toggle state.";
  }

  if (componentName === "NuiProgress" && arg.type === "json" && arg.name === "jValue") {
    if (isNuiBindToken(v)) return null;
    if (isJsonNumberCompatibleExpression(v)) return null;
    return "Expected float expression: NuiBind(...), JsonInt/JsonFloat(...), number, or constant token.";
  }

  if (
    (componentName === "NuiWidth" && arg.type === "float" && arg.name === "fWidth") ||
    (componentName === "NuiHeight" && arg.type === "float" && arg.name === "fHeight")
  ) {
    if (isDotFloatToken(v)) return null;
    return 'Expected explicit float literal with dot (e.g. 180.0). Comma "," is not allowed.';
  }

  if ((componentName === "NuiSlider" || componentName === "NuiSliderFloat") && arg.type === "json") {
    if (arg.name === "jValue" || arg.name === "jMin" || arg.name === "jMax" || arg.name === "jStepSize") {
      if (isNuiBindToken(v)) return null;
      if (componentName === "NuiSlider") {
        if (!isJsonIntCompatibleExpression(v)) {
          return "Expected discrete int expression: NuiBind(...), JsonInt(...), int, or constant token.";
        }
      } else if (!isJsonNumberCompatibleExpression(v)) {
        return "Expected numeric expression: NuiBind(...), JsonInt/JsonFloat(...), number, or constant token.";
      }
    }
  }

  if ((componentName === "NuiOptions" || componentName === "NuiToggles") && arg.type === "json") {
    if (arg.name === "jElements") {
      if (isNuiBindToken(v) || isJsonNullToken(v)) return null;
      if (parseJsonStringElements(v) !== null) return null;
      return 'Expected JsonArray() / JsonArrayInsert(..., JsonString("Label")) chain or NuiBind(...).';
    }
    if (arg.name === "jValue") {
      if (isNuiBindToken(v) || isJsonNullToken(v)) return null;
      if (!isJsonIntCompatibleExpression(v)) {
        return "Expected JsonInt/int/constant token or NuiBind(...).";
      }
      const literal = parseJsonIntLiteral(v);
      if (componentName === "NuiOptions" && literal !== null && literal < -1) {
        return "NuiOptions uses -1 for no selection, otherwise >= 0.";
      }
      if (componentName === "NuiToggles" && literal !== null && literal < -1) {
        return "NuiToggles uses -1 for no selection, otherwise >= 0.";
      }
      return null;
    }
  }

  if (componentName === "NuiList" && arg.type === "json" && arg.name === "jRowCount") {
    if (isNuiBindToken(v)) return null;
    if (isJsonIntCompatibleExpression(v)) {
      const literal = parseJsonIntLiteral(v);
      if (literal !== null && literal < 0) {
        return "jRowCount cannot be negative.";
      }
      return null;
    }
    return "Expected JsonInt(<int>), int/constant token, or NuiBind(...).";
  }

  if (componentName === "NuiListTemplateCell" && arg.type === "float" && arg.name === "fWidth") {
    if (isFloatToken(v)) {
      if (Number(v) < 0) return "fWidth cannot be negative (0 = auto, >1 = fixed px hint).";
      return null;
    }
    if (isConstantToken(v)) return null;
    return "Expected float/constant token (0 = auto, >1 = fixed px hint).";
  }

  if (componentName === "NuiList" && arg.type === "float" && arg.name === "fRowHeight") {
    if (isFloatToken(v)) {
      if (Number(v) <= 0) return "fRowHeight must be > 0.";
      return null;
    }
    if (isConstantToken(v)) return null;
    return "Expected float/constant token.";
  }

  if (componentName === "NuiTextEdit" && arg.type === "int") {
    if (arg.name === "nMaxLength") {
      if (isConstantToken(v)) return null;
      if (!isIntToken(v)) {
        return `Expected int/constant in range ${NUI_TEXT_EDIT_MIN_LENGTH}..${NUI_TEXT_EDIT_MAX_LENGTH}.`;
      }
      const numeric = Number(v);
      if (numeric < NUI_TEXT_EDIT_MIN_LENGTH || numeric > NUI_TEXT_EDIT_MAX_LENGTH) {
        return `nMaxLength must be in range ${NUI_TEXT_EDIT_MIN_LENGTH}..${NUI_TEXT_EDIT_MAX_LENGTH}.`;
      }
      return null;
    }
    if (arg.name === "bMultiline" || arg.name === "bWordWrap") {
      if (isBoolIntCompatibleExpression(v)) return null;
      return "Expected TRUE/FALSE, 0/1, or boolean constant token.";
    }
  }

  if (arg.type === "int") {
    if (parsePlainBool(v) !== null || isIntToken(v) || isConstantToken(v)) {
      return null;
    }
    return "Expected integer / bool / constant token for int.";
  }

  if (arg.type === "float") {
    if (isFloatToken(v) || isConstantToken(v)) {
      return null;
    }
    return "Expected float number or constant token for float.";
  }

  return null;
}

function previewTextValue(raw: string | undefined, fallback: string): string {
  const value = String(raw ?? "").trim();
  if (!value || value === "JSON_NULL" || value === "JSON_STRING") return fallback;

  const bind = parseNuiBindDescriptor(value);
  if (bind) {
    const bindPreview = `{${bind.id}}`;
    return applyBindTextFlags(bindPreview, bind.textFlags);
  }

  const jsonStr = value.match(/^JsonString\("((?:\\.|[^"\\])*)"\)$/);
  if (jsonStr) return unescapeNwString(jsonStr[1]);

  const quoted = value.match(/^"((?:\\.|[^"\\])*)"$/);
  if (quoted) return unescapeNwString(quoted[1]);

  const strRef = parseNuiStrRefToken(value);
  if (strRef !== null) return `<strref:${strRef}>`;

  return value;
}

function parsePreviewBindValues(raw: string | undefined): Record<string, JuiImportValue[]> {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    const out: Record<string, JuiImportValue[]> = {};
    Object.entries(parsed as Record<string, unknown>).forEach(([key, value]) => {
      if (Array.isArray(value)) out[key] = value as JuiImportValue[];
    });
    return out;
  } catch {
    return {};
  }
}

function parseListPreviewRowsJson(raw: string | undefined): ListPreviewRow[] | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return null;
    const rows: ListPreviewRow[] = [];
    for (const entry of parsed) {
      if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
        rows.push({});
        continue;
      }
      const row: ListPreviewRow = {};
      const record = entry as Record<string, unknown>;
      for (const [bindId, value] of Object.entries(record)) {
        if (value === null || typeof value === "string" || typeof value === "number" || typeof value === "boolean" || isJuiImportObject(value) || Array.isArray(value)) {
          row[bindId] = value as JuiImportValue;
        }
      }
      rows.push(row);
    }
    return rows;
  } catch {
    return null;
  }
}

function buildListPreviewRowsFromBindMap(bindMap: Record<string, JuiImportValue[]>): ListPreviewRow[] {
  const bindIds = Object.keys(bindMap);
  if (!bindIds.length) return [];
  const rowCount = bindIds.reduce((count, bindId) => Math.max(count, bindMap[bindId]?.length ?? 0), 0);
  return Array.from({ length: rowCount }, (_, rowIndex) => {
    const row: ListPreviewRow = {};
    bindIds.forEach((bindId) => {
      const value = bindMap[bindId]?.[rowIndex];
      if (value !== undefined) {
        row[bindId] = value;
      }
    });
    return row;
  });
}

function buildListPreviewBindMapFromRows(rows: ListPreviewRow[], bindIds: string[]): Record<string, JuiImportValue[]> {
  const sourceIds = bindIds.length > 0 ? bindIds : Array.from(new Set(rows.flatMap((row) => Object.keys(row))));
  if (!sourceIds.length) return {};

  const out: Record<string, JuiImportValue[]> = {};
  sourceIds.forEach((id) => {
    out[id] = [];
  });
  rows.forEach((row, rowIndex) => {
    sourceIds.forEach((bindId) => {
      if (Object.prototype.hasOwnProperty.call(row, bindId)) {
        out[bindId][rowIndex] = row[bindId];
      }
    });
  });
  return out;
}

function deriveListPreviewRowsFromProps(props: Record<string, string>): ListPreviewRow[] {
  const parsedRows = parseListPreviewRowsJson(props.__previewRowsJson);
  if (parsedRows) return parsedRows;
  const legacyPreview = parsePreviewBindValues(props.__previewBinds);
  return buildListPreviewRowsFromBindMap(legacyPreview);
}

function collectListTemplateBindIdsFromNode(node: NuiNode, seenIds: Set<string>, orderedIds: string[]): void {
  for (const value of Object.values(node.props || {})) {
    const bind = parseNuiBindDescriptor(value);
    if (!bind || !bind.id.trim() || seenIds.has(bind.id)) continue;
    seenIds.add(bind.id);
    orderedIds.push(bind.id);
  }
  node.children.forEach((child) => {
    collectListTemplateBindIdsFromNode(child, seenIds, orderedIds);
  });
}

function collectListTemplateBindIdsFromListTemplateChildren(nodes: NuiNode[]): string[] {
  const orderedIds: string[] = [];
  const seenIds = new Set<string>();
  for (const node of nodes) {
    collectListTemplateBindIdsFromNode(node, seenIds, orderedIds);
  }
  return orderedIds;
}

function listCellValueInputToJuiImport(raw: string): JuiImportValue {
  const value = raw.trim();
  if (!value) return "";

  const jsonString = parseJsonStringLiteral(value);
  if (jsonString !== null) return jsonString;

  if (value === "null") return null;
  const parsedBool = parsePlainBool(value);
  if (parsedBool !== null) return parsedBool;
  const parsedJson = (() => {
    if (value.startsWith("{") && value.endsWith("}")) {
      return true;
    }
    if (value.startsWith("[") && value.endsWith("]")) {
      return true;
    }
    return false;
  })();
  if (parsedJson) {
    try {
      const parsedValue = JSON.parse(value) as unknown;
      if (parsedValue === null || typeof parsedValue === "boolean" || typeof parsedValue === "number" || typeof parsedValue === "string") {
        return parsedValue;
      }
      if (isJuiImportObject(parsedValue) || Array.isArray(parsedValue)) {
        return parsedValue as JuiImportValue;
      }
    } catch {
      // fall through
    }
  }

  if (isIntToken(value)) return Number(value);
  if (isFloatToken(value)) return Number(value);

  return raw;
}

function formatListPreviewRowCell(rowValue: JuiImportValue | undefined): string {
  if (rowValue === undefined || rowValue === null) return "";
  if (typeof rowValue === "string") return rowValue;
  if (typeof rowValue === "number" || typeof rowValue === "boolean") return String(rowValue);
  return JSON.stringify(rowValue);
}

function previewTextValueForRender(raw: string | undefined, fallback: string, renderCtx: LiveRenderContext): string {
  const value = String(raw ?? "").trim();
  const bind = parseNuiBindDescriptor(value);
  if (bind && typeof renderCtx.listRowIndex === "number" && renderCtx.previewBinds?.[bind.id]) {
    const rowValue = renderCtx.previewBinds[bind.id][renderCtx.listRowIndex];
    if (typeof rowValue === "string") return applyBindTextFlags(rowValue, bind.textFlags);
    if (typeof rowValue === "number" || typeof rowValue === "boolean") return applyBindTextFlags(String(rowValue), bind.textFlags);
  }
  return previewTextValue(raw, fallback);
}

function unescapeNwString(value: string): string {
  let out = "";
  for (let i = 0; i < value.length; i += 1) {
    const ch = value[i];
    if (ch !== "\\" || i + 1 >= value.length) {
      out += ch;
      continue;
    }

    const next = value[i + 1];
    i += 1;
    if (next === "n") {
      out += "\n";
    } else if (next === "r") {
      out += "\r";
    } else if (next === "t") {
      out += "\t";
    } else if (next === "\\" || next === '"') {
      out += next;
    } else {
      out += next;
    }
  }
  return out;
}

function escapeNwString(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function parseNuiIdValue(raw: string | undefined): string {
  const value = String(raw ?? "").trim();
  if (!value) return "";

  const quoted = value.match(/^"((?:\\.|[^"\\])*)"$/);
  if (quoted) return unescapeNwString(quoted[1]).trim();

  const jsonString = value.match(/^JsonString\("((?:\\.|[^"\\])*)"\)$/);
  if (jsonString) return unescapeNwString(jsonString[1]).trim();

  return value.trim();
}

function toNuiIdLiteral(id: string): string {
  return `"${escapeNwString(id)}"`;
}

function isDrawPrimitiveComponentName(name: string): boolean {
  return name.startsWith("NuiDrawList") && name !== "NuiDrawList";
}

function isListTemplateCellLikeComponentName(name: string): boolean {
  return name === "NuiListTemplateCell";
}

function defaultElementLabels(): string[] {
  return ["Label 1", "Label 2", "Label 3"];
}

function buildElementsValue(componentName: string, labels: string[]): string {
  void componentName;
  const clean = labels.map((label) => label.trim()).filter((label) => label.length > 0);
  if (!clean.length) return "JsonArray()";

  return clean.reduce((expr, label) => `JsonArrayInsert(${expr}, JsonString("${escapeNwString(label)}"))`, "JsonArray()");
}

function parseJsonStringElements(raw: string | undefined): string[] | null {
  const value = String(raw ?? "").trim();
  if (!value) return null;
  if (/^JsonArray\(\)$/i.test(value)) return [];

  const items = parseJsonArrayInsertItems(value);
  if (!items) return null;

  const labels: string[] = [];
  for (const item of items) {
    const parsed = parseQuotedOrJsonString(item);
    if (parsed === null) return null;
    labels.push(parsed);
  }
  return labels;
}

function parseElementLabels(raw: string | undefined, fallback: string[]): string[] {
  const value = String(raw ?? "").trim();
  if (!value || value === "JSON_NULL" || isNuiBindToken(value)) return fallback;
  if (/^JsonArray\(\)$/i.test(value)) return [];

  const stringItems = parseJsonStringElements(value);
  if (stringItems) return stringItems;

  const comboLabels = [...value.matchAll(/NuiComboEntry\("((?:\\.|[^"\\])*)"\s*,/g)].map((match) => unescapeNwString(match[1]));
  if (comboLabels.length) return comboLabels;

  const jsonStringLabels = [...value.matchAll(/JsonString\("((?:\\.|[^"\\])*)"\)/g)].map((match) => unescapeNwString(match[1]));
  if (jsonStringLabels.length) return jsonStringLabels;

  return fallback;
}

function parseComboEntries(raw: string | undefined, fallback: string[]): ComboPreviewEntry[] {
  const value = String(raw ?? "").trim();
  const fallbackEntries = fallback.map((label, index) => ({ label, value: index }));
  if (!value || value === "JSON_NULL" || isNuiBindToken(value)) return fallbackEntries;
  if (/^JsonArray\(\)$/i.test(value)) return [];
  const parsed = tryParseComboEntries(value);
  if (parsed) return parsed;

  const jsonStringLabels = [...value.matchAll(/JsonString\("((?:\\.|[^"\\])*)"\)/g)].map((match) => unescapeNwString(match[1]));
  if (jsonStringLabels.length) {
    return jsonStringLabels.map((label, index) => ({ label, value: index }));
  }

  return fallbackEntries;
}

function previewNumberValue(raw: string | undefined, fallback: number): number {
  const value = String(raw ?? "").trim();
  if (!value) return fallback;

  const jsonInt = value.match(/^JsonInt\((-?\d+)\)$/i);
  if (jsonInt) return Number(jsonInt[1]);

  const jsonFloat = value.match(/^JsonFloat\((-?\d+(\.\d+)?)\)$/i);
  if (jsonFloat) return Number(jsonFloat[1]);

  if (isFloatToken(value)) return Number(value);
  return fallback;
}

function previewTextEditMaxLength(raw: string | undefined, fallback: number): number {
  const value = String(raw ?? "").trim();
  if (!value) return fallback;
  if (isIntToken(value)) {
    return Math.max(NUI_TEXT_EDIT_MIN_LENGTH, Math.min(NUI_TEXT_EDIT_MAX_LENGTH, Number(value)));
  }
  return fallback;
}

function previewBoolValue(raw: string | undefined, fallback: boolean): boolean {
  const value = String(raw ?? "").trim();
  if (!value) return fallback;

  const plain = parsePlainBool(value);
  if (plain !== null) return plain;

  const json = parseJsonBool(value);
  if (json !== null) return json;

  return fallback;
}

function previewDirectionValue(raw: string | undefined, fallback: number): number {
  const parsed = parseDirectionLiteral(raw);
  return parsed === null ? fallback : parsed;
}

function parseDirectionLiteral(raw: string | undefined): number | null {
  const value = String(raw ?? "").trim();
  if (!value) return null;

  if (isIntToken(value)) {
    const numeric = Number(value);
    return numeric === 0 || numeric === 1 ? numeric : null;
  }

  const jsonInt = value.match(/^JsonInt\(([^)]+)\)$/i);
  if (jsonInt) {
    const candidate = jsonInt[1].trim();
    if (isIntToken(candidate)) {
      const numeric = Number(candidate);
      return numeric === 0 || numeric === 1 ? numeric : null;
    }
    const upperCandidate = candidate.toUpperCase();
    if (upperCandidate === "NUI_DIRECTION_HORIZONTAL") return 0;
    if (upperCandidate === "NUI_DIRECTION_VERTICAL") return 1;
    return null;
  }

  const upper = value.toUpperCase();
  if (upper === "NUI_DIRECTION_HORIZONTAL") return 0;
  if (upper === "NUI_DIRECTION_VERTICAL") return 1;
  if (upper.includes("HORIZONTAL")) return 0;
  if (upper.includes("VERTICAL")) return 1;
  return null;
}

function previewScrollMode(raw: string | undefined, fallback: number): number {
  const value = String(raw ?? "").trim();
  if (!value) return fallback;

  const jsonInt = value.match(/^JsonInt\(([^)]+)\)$/i);
  const candidate = (jsonInt ? jsonInt[1] : value).trim();
  const upper = candidate.toUpperCase();

  if (upper === "NUI_SCROLLBARS_NONE") return 0;
  if (upper === "NUI_SCROLLBARS_X") return 1;
  if (upper === "NUI_SCROLLBARS_Y") return 2;
  if (upper === "NUI_SCROLLBARS_BOTH") return 3;
  if (upper === "NUI_SCROLLBARS_AUTO") return 4;

  if (isIntToken(candidate)) {
    const numeric = Number(candidate);
    if (numeric >= 0 && numeric <= 4) return numeric;
  }

  return fallback;
}

function previewDrawRenderMode(raw: string | undefined, fallback: number): number {
  const value = String(raw ?? "").trim();
  if (!value) return fallback;

  const jsonInt = value.match(/^JsonInt\(([^)]+)\)$/i);
  const candidate = (jsonInt ? jsonInt[1] : value).trim();
  const upper = candidate.toUpperCase();

  if (upper === "NUI_DRAW_LIST_ITEM_RENDER_ALWAYS") return 0;
  if (upper === "NUI_DRAW_LIST_ITEM_RENDER_MOUSE_OFF") return 1;
  if (upper === "NUI_DRAW_LIST_ITEM_RENDER_MOUSE_HOVER") return 2;
  if (upper === "NUI_DRAW_LIST_ITEM_RENDER_MOUSE_LEFT") return 3;
  if (upper === "NUI_DRAW_LIST_ITEM_RENDER_MOUSE_RIGHT") return 4;
  if (upper === "NUI_DRAW_LIST_ITEM_RENDER_MOUSE_MIDDLE") return 5;

  if (isIntToken(candidate)) {
    const numeric = Number(candidate);
    if (numeric >= 0 && numeric <= 5) return numeric;
  }

  return fallback;
}

function previewDrawOrder(raw: string | undefined, fallback: number): number {
  const value = String(raw ?? "").trim();
  if (!value) return fallback;

  const jsonInt = value.match(/^JsonInt\(([^)]+)\)$/i);
  const candidate = (jsonInt ? jsonInt[1] : value).trim();
  const upper = candidate.toUpperCase();

  if (upper === "NUI_DRAW_LIST_ITEM_ORDER_BEFORE") return -1;
  if (upper === "NUI_DRAW_LIST_ITEM_ORDER_AFTER") return 1;

  if (isIntToken(candidate)) {
    const numeric = Number(candidate);
    if (numeric < 0) return -1;
    if (numeric > 0) return 1;
  }

  return fallback;
}

function previewDrawScissorEnabled(raw: string | undefined, fallback: boolean): boolean {
  const value = String(raw ?? "").trim();
  if (!value) return fallback;

  const plain = parsePlainBool(value);
  if (plain !== null) return plain;

  const jsonBool = parseJsonBool(value);
  if (jsonBool !== null) return jsonBool;

  const jsonInt = value.match(/^JsonInt\(([^)]+)\)$/i);
  const candidate = (jsonInt ? jsonInt[1] : value).trim();
  if (isIntToken(candidate)) return Number(candidate) !== 0;

  return fallback;
}

function isImagePreviewLeafNode(node: NuiNode | null): boolean {
  if (!node) return false;
  if (node.componentName === "NuiImage" || node.componentName === "NuiButtonImage" || node.componentName === "NuiDrawListImage") return true;
  if (
    node.componentName === "NuiWidth" ||
    node.componentName === "NuiHeight" ||
    node.componentName === "NuiAspect" ||
    node.componentName === "NuiMargin" ||
    node.componentName === "NuiPadding" ||
    node.componentName === "NuiEnabled" ||
    node.componentName === "NuiVisible" ||
    node.componentName === "NuiTooltip" ||
    node.componentName === "NuiDisabledTooltip" ||
    node.componentName === "NuiEncouraged" ||
    node.componentName === "NuiStyleForegroundColor" ||
    node.componentName === "NuiStyleFont" ||
    node.componentName === "NuiImageRegion" ||
    node.componentName === "NuiDrawListImageRegion" ||
    node.componentName === "NuiId"
  ) {
    return isImagePreviewLeafNode(node.children[0] ?? null);
  }
  return false;
}

function resolveEncouragedButtonSkinToken(
  isSelected: boolean,
  renderCtx: LiveRenderContext,
): "nui_button_n" | "nui_button_h" | "nui_button_a" | "nui_button_ah" {
  const pulseOn = renderCtx.encouragedActive === true && renderCtx.encouragedPulseOn === true;
  if (isSelected) {
    return pulseOn ? "nui_button_ah" : "nui_button_a";
  }
  return pulseOn ? "nui_button_h" : "nui_button_n";
}

interface DrawHostRenderState {
  hover: boolean;
  left: boolean;
  right: boolean;
  middle: boolean;
}

function findDrawRenderCarrierNode(node: NuiNode): NuiNode {
  if (Object.prototype.hasOwnProperty.call(node.props, "nRender")) return node;
  for (const child of node.children) {
    const candidate = findDrawRenderCarrierNode(child);
    if (Object.prototype.hasOwnProperty.call(candidate.props, "nRender")) return candidate;
  }
  return node;
}

function shouldRenderDrawItemForHostState(node: NuiNode, hostState: DrawHostRenderState): boolean {
  const carrier = findDrawRenderCarrierNode(node);
  const enabled = previewBoolValue(carrier.props.jEnabled, true);
  if (!enabled) return false;

  const mode = previewDrawRenderMode(carrier.props.nRender, 0);
  if (mode === 0) return true;
  if (mode === 1) return !hostState.hover;
  if (mode === 2) return hostState.hover;
  if (mode === 3) return hostState.left;
  if (mode === 4) return hostState.right;
  if (mode === 5) return hostState.middle;
  return true;
}

function previewImageObjectFit(raw: string | undefined): React.CSSProperties["objectFit"] {
  const value = String(raw ?? "").trim();
  const upper = value.toUpperCase();
  if (upper.includes("NUI_ASPECT_FILL")) return "cover";
  if (upper.includes("NUI_ASPECT_STRETCH") || upper.includes("NUI_ASPECT_EXACT")) return "fill";
  if (upper.includes("NUI_ASPECT_FIT100")) return "scale-down";
  if (isIntToken(value)) {
    const numeric = Number(value);
    if (numeric === 1) return "cover";
    if (numeric === 5 || numeric === 3 || numeric === 4) return "fill";
    if (numeric === 2) return "scale-down";
  }
  return "contain";
}

function previewImageAxisAlign(raw: string | undefined, axis: "x" | "y"): "left" | "center" | "right" | "top" | "bottom" {
  const value = String(raw ?? "").trim();
  const upper = value.toUpperCase();
  if (axis === "x") {
    if (upper.includes("NUI_HALIGN_LEFT")) return "left";
    if (upper.includes("NUI_HALIGN_RIGHT")) return "right";
    if (isIntToken(value)) {
      const numeric = Number(value);
      if (numeric === 1) return "left";
      if (numeric === 2) return "right";
    }
    return "center";
  }
  if (upper.includes("NUI_VALIGN_TOP")) return "top";
  if (upper.includes("NUI_VALIGN_BOTTOM")) return "bottom";
  if (isIntToken(value)) {
    const numeric = Number(value);
    if (numeric === 1) return "top";
    if (numeric === 2) return "bottom";
  }
  return "center";
}

function previewLabelTextAlign(raw: string | undefined): React.CSSProperties["textAlign"] {
  const align = previewImageAxisAlign(raw, "x");
  return align === "left" || align === "right" ? align : "center";
}

function previewLabelVerticalAlign(raw: string | undefined): React.CSSProperties["alignItems"] {
  const align = previewImageAxisAlign(raw, "y");
  if (align === "top") return "flex-start";
  if (align === "bottom") return "flex-end";
  return "center";
}

function isJsonNullToken(raw: string | undefined): boolean {
  const value = String(raw ?? "").trim();
  return value === "JSON_NULL" || /^JsonNull\(\)$/i.test(value);
}

function isNuiBindToken(raw: string | undefined): boolean {
  return parseNuiBindDescriptor(raw) !== null;
}

interface PreviewNuiRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface PreviewNuiVec {
  x: number;
  y: number;
}

function parseNuiPointArrayValue(raw: string | undefined): PreviewNuiVec[] | null {
  const value = String(raw ?? "").trim();
  if (!value || value === "JSON_NULL") return null;

  if (value.startsWith("[") && value.endsWith("]")) {
    try {
      const parsed = JSON.parse(value) as unknown;
      if (Array.isArray(parsed)) {
        if (parsed.every((entry) => typeof entry === "number")) {
          const out: PreviewNuiVec[] = [];
          for (let idx = 0; idx + 1 < parsed.length; idx += 2) {
            out.push({ x: Number(parsed[idx]), y: Number(parsed[idx + 1]) });
          }
          return out.length ? out : null;
        }
        const out: PreviewNuiVec[] = [];
        for (const entry of parsed) {
          if (!entry || typeof entry !== "object") continue;
          const maybeX = (entry as Record<string, unknown>).x;
          const maybeY = (entry as Record<string, unknown>).y;
          if (typeof maybeX === "number" && typeof maybeY === "number") {
            out.push({ x: maybeX, y: maybeY });
          }
        }
        return out.length ? out : null;
      }
    } catch {
      // fall through to expression scanners
    }
  }

  const vecMatches = [...value.matchAll(/NuiVec\(\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*\)/gi)];
  if (vecMatches.length) {
    return vecMatches.map((match) => ({ x: Number(match[1]), y: Number(match[2]) }));
  }

  const numericMatches = [...value.matchAll(/(?:JsonFloat|JsonInt)\(\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*\)/gi)];
  if (numericMatches.length >= 2) {
    const values = numericMatches.map((match) => Number(match[1]));
    const out: PreviewNuiVec[] = [];
    for (let idx = 0; idx + 1 < values.length; idx += 2) {
      out.push({ x: values[idx], y: values[idx + 1] });
    }
    return out.length ? out : null;
  }

  return null;
}

function formatSvgNumber(value: number): string {
  if (!Number.isFinite(value)) return "0";
  const fixed = value.toFixed(3);
  return fixed.replace(/\.?0+$/, "") || "0";
}

function buildArcPath(center: PreviewNuiVec, radius: number, aMin: number, aMax: number, fill: boolean): string {
  const tau = Math.PI * 2;
  const deltaRaw = aMax - aMin;
  const clockwise = deltaRaw >= 0;
  let span = Math.abs(deltaRaw);
  if (span < 1e-6) span = 1e-6;
  if (span >= tau) span = tau - 1e-4;
  const endAngle = aMin + (clockwise ? span : -span);

  const start = {
    x: center.x + Math.cos(aMin) * radius,
    y: center.y + Math.sin(aMin) * radius,
  };
  const end = {
    x: center.x + Math.cos(endAngle) * radius,
    y: center.y + Math.sin(endAngle) * radius,
  };
  const largeArc = span > Math.PI ? 1 : 0;
  const sweep = clockwise ? 1 : 0;

  if (fill) {
    return [
      `M ${formatSvgNumber(center.x)} ${formatSvgNumber(center.y)}`,
      `L ${formatSvgNumber(start.x)} ${formatSvgNumber(start.y)}`,
      `A ${formatSvgNumber(radius)} ${formatSvgNumber(radius)} 0 ${largeArc} ${sweep} ${formatSvgNumber(end.x)} ${formatSvgNumber(end.y)}`,
      "Z",
    ].join(" ");
  }

  return [
    `M ${formatSvgNumber(start.x)} ${formatSvgNumber(start.y)}`,
    `A ${formatSvgNumber(radius)} ${formatSvgNumber(radius)} 0 ${largeArc} ${sweep} ${formatSvgNumber(end.x)} ${formatSvgNumber(end.y)}`,
  ].join(" ");
}

function parseNuiVecValue(raw: string | undefined): PreviewNuiVec | null {
  const value = String(raw ?? "").trim();
  if (!value || value === "JSON_NULL") return null;

  const vec = value.match(/^NuiVec\(\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*\)$/i);
  if (vec) {
    return {
      x: Number(vec[1]),
      y: Number(vec[2]),
    };
  }

  const objectStyle = value.match(/^\{\s*"?(x|X)"?\s*:\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*"?(y|Y)"?\s*:\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*\}$/);
  if (objectStyle) {
    return {
      x: Number(objectStyle[2]),
      y: Number(objectStyle[4]),
    };
  }

  return null;
}

function parseNuiRectValue(raw: string | undefined): PreviewNuiRect | null {
  const value = String(raw ?? "").trim();
  if (!value || value === "JSON_NULL") return null;

  const rectCall = value.match(/^NuiRect\(\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*\)$/i);
  if (rectCall) {
    return {
      x: Number(rectCall[1]),
      y: Number(rectCall[2]),
      w: Number(rectCall[3]),
      h: Number(rectCall[4]),
    };
  }

  if (value.startsWith("{") && value.endsWith("}")) {
    try {
      const parsed = JSON.parse(value) as Record<string, unknown>;
      const x = typeof parsed.x === "number" ? parsed.x : Number.NaN;
      const y = typeof parsed.y === "number" ? parsed.y : Number.NaN;
      const w = typeof parsed.w === "number" ? parsed.w : Number.NaN;
      const h = typeof parsed.h === "number" ? parsed.h : Number.NaN;
      if ([x, y, w, h].every((entry) => Number.isFinite(entry))) {
        return { x, y, w, h };
      }
    } catch {
      // Keep legacy/custom expressions untouched when they are not strict JSON.
    }
  }

  return null;
}

function parseWindowSizeConstraint(raw: string | undefined): PreviewWindowSizeConstraint | null {
  if (isJsonNullToken(raw) || isNuiBindToken(raw)) return null;
  const rect = parseNuiRectValue(raw);
  if (!rect) return null;
  return {
    minW: rect.x > 0 ? rect.x : null,
    minH: rect.y > 0 ? rect.y : null,
    maxW: rect.w > 0 ? rect.w : null,
    maxH: rect.h > 0 ? rect.h : null,
  };
}

function clampWindowDimension(value: number, min: number | null, max: number | null): number {
  let next = clampWindowSize(value);
  if (min !== null) next = Math.max(next, Math.round(min));
  if (max !== null) next = Math.min(next, Math.round(max));
  if (min !== null && max !== null && min > max) {
    next = Math.max(100, Math.round(min));
  }
  return Math.max(100, next);
}

function clampByte(value: number): number {
  return Math.max(0, Math.min(255, Math.round(value)));
}

function parseNuiColorLiteral(raw: string | undefined): PreviewNuiColor | null {
  const value = String(raw ?? "").trim();
  if (!value || value === "JSON_NULL") return null;
  const color = value.match(/^([A-Za-z_][A-Za-z0-9_]*)\(([^)]*)\)$/);
  if (color) {
    const fn = color[1].toUpperCase();
    if (fn !== "NUICOLOR" && fn !== "JSONCOLOR") return null;
    const parts = color[2]
      .split(",")
      .map((part) => part.trim())
      .filter((part) => part.length > 0);
    if (parts.length < 3 || parts.length > 4) return null;
    if (!parts.every((part) => isIntToken(part))) return null;
    const r = Number(parts[0]);
    const g = Number(parts[1]);
    const b = Number(parts[2]);
    const a = parts[3] !== undefined ? Number(parts[3]) : 255;
    return { r, g, b, a };
  }

  if (value.startsWith("{") && value.endsWith("}")) {
    try {
      const parsed = JSON.parse(value) as Record<string, unknown>;
      const r = parsed.r;
      const g = parsed.g;
      const b = parsed.b;
      const a = parsed.a;
      if (!Number.isInteger(r) || !Number.isInteger(g) || !Number.isInteger(b)) {
        return null;
      }
      if (a !== undefined && !Number.isInteger(a)) {
        return null;
      }
      return {
        r: Number(r),
        g: Number(g),
        b: Number(b),
        a: a === undefined ? 255 : Number(a),
      };
    } catch {
      return null;
    }
  }

  return null;
}

function formatNuiColorLiteral(color: PreviewNuiColor): string {
  const r = Number.isFinite(color.r) ? Math.round(color.r) : 0;
  const g = Number.isFinite(color.g) ? Math.round(color.g) : 0;
  const b = Number.isFinite(color.b) ? Math.round(color.b) : 0;
  const a = Number.isFinite(color.a) ? Math.round(color.a) : 255;
  if (a === 255) {
    return `NuiColor(${r}, ${g}, ${b})`;
  }
  return `NuiColor(${r}, ${g}, ${b}, ${a})`;
}

function nuiColorToHex(color: PreviewNuiColor): string {
  const toHex = (value: number) => clampByte(value).toString(16).padStart(2, "0");
  return `#${toHex(color.r)}${toHex(color.g)}${toHex(color.b)}`;
}

function parseHexColorValue(raw: string): { r: number; g: number; b: number } | null {
  const value = raw.trim();
  const hex = value.match(/^#?([0-9a-fA-F]{6})$/);
  if (!hex) return null;
  const compact = hex[1];
  return {
    r: Number.parseInt(compact.slice(0, 2), 16),
    g: Number.parseInt(compact.slice(2, 4), 16),
    b: Number.parseInt(compact.slice(4, 6), 16),
  };
}

function clampUnit(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(1, value));
}

function rgbToHsv(color: PreviewNuiColor): { h: number; s: number; v: number } {
  const r = clampByte(color.r) / 255;
  const g = clampByte(color.g) / 255;
  const b = clampByte(color.b) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;
  let h = 0;
  if (delta > 0) {
    if (max === r) h = ((g - b) / delta) % 6;
    else if (max === g) h = (b - r) / delta + 2;
    else h = (r - g) / delta + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  const s = max === 0 ? 0 : delta / max;
  return {
    h: Number.isFinite(h) ? h : 0,
    s: clampUnit(s),
    v: clampUnit(max),
  };
}

function hsvToRgb(h: number, s: number, v: number): { r: number; g: number; b: number } {
  const sat = clampUnit(s);
  const val = clampUnit(v);
  const hue = (((Number.isFinite(h) ? h : 0) % 360) + 360) % 360;
  const c = val * sat;
  const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
  const m = val - c;
  let rp = 0;
  let gp = 0;
  let bp = 0;
  if (hue < 60) {
    rp = c;
    gp = x;
  } else if (hue < 120) {
    rp = x;
    gp = c;
  } else if (hue < 180) {
    gp = c;
    bp = x;
  } else if (hue < 240) {
    gp = x;
    bp = c;
  } else if (hue < 300) {
    rp = x;
    bp = c;
  } else {
    rp = c;
    bp = x;
  }
  return {
    r: clampByte((rp + m) * 255),
    g: clampByte((gp + m) * 255),
    b: clampByte((bp + m) * 255),
  };
}

function parseJsonStringLiteral(raw: string | undefined): string | null {
  const value = String(raw ?? "").trim();
  if (!value) return null;
  if (value === "JSON_STRING") return "";
  const jsonString = value.match(/^JsonString\("(.*)"\)$/);
  if (jsonString) return unescapeNwString(jsonString[1]);
  const quoted = value.match(/^"(.*)"$/);
  if (quoted) return unescapeNwString(quoted[1]);
  return null;
}

function previewWindowFontFamily(raw: string | undefined): string | null {
  if (isJsonNullToken(raw) || isNuiBindToken(raw)) return null;
  const token = parseJsonStringLiteral(raw);
  if (token === null) return null;
  const normalized = token.trim().toLowerCase();
  if (!normalized || normalized === "(default)") return null;
  if (normalized === "(monospace)") return '"JetBrains Mono", "Consolas", "Courier New", monospace';
  return `"${token}", "Inter", sans-serif`;
}

function windowFontNameFromValue(raw: string | undefined): string | null {
  if (isJsonNullToken(raw) || isNuiBindToken(raw)) return null;
  const token = parseJsonStringLiteral(raw);
  if (token === null) return null;
  return token.trim() || "(default)";
}

function windowFontValueFromName(name: string): string {
  const normalized = name.trim();
  if (!normalized || normalized === "(default)") return "JSON_STRING";
  return toJsonStringLiteral(normalized);
}

function normalizeConstraintRectValue(value: string): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return 0;
  return Math.max(0, parsed);
}

function normalizeRectEditorValue(value: string, fallback: number): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return parsed;
}

function normalizeFloatLiteralInput(value: string): string {
  return value.replace(/,/g, ".").replace(/\s+/g, "");
}

function clampWindowSize(value: number): number {
  return Math.max(100, Math.round(value));
}

function normalizeResolutionDimension(raw: number | undefined, fallback: number): number {
  if (!Number.isFinite(raw)) return fallback;
  return Math.max(RESOLUTION_MIN, Math.min(RESOLUTION_MAX, Math.round(raw as number)));
}

function detectInitialScreenResolution(): { width: number; height: number } {
  if (typeof window === "undefined" || !window.screen) {
    return { width: RESOLUTION_DEFAULT_WIDTH, height: RESOLUTION_DEFAULT_HEIGHT };
  }
  const width = normalizeResolutionDimension(window.screen.width, RESOLUTION_DEFAULT_WIDTH);
  const height = normalizeResolutionDimension(window.screen.height, RESOLUTION_DEFAULT_HEIGHT);
  return { width, height };
}

function resolveGeometryAxis(raw: number, resolution: number, size: number): { value: number; mode: "absolute" | "center" | "cursor" } {
  if (isNearly(raw, -1.0)) {
    return { value: Math.round((resolution - size) / 2), mode: "center" };
  }
  if (isNearly(raw, -2.0) || isNearly(raw, -3.0)) {
    return { value: Math.round((resolution - size) / 2), mode: "cursor" };
  }
  return { value: Math.round(raw), mode: "absolute" };
}

function buildVisualPositionSnapshot(
  geometry: PreviewNuiRect | null,
  resolutionWidth: number,
  resolutionHeight: number,
): VisualPositionSnapshot {
  const safeResolutionWidth = normalizeResolutionDimension(resolutionWidth, RESOLUTION_DEFAULT_WIDTH);
  const safeResolutionHeight = normalizeResolutionDimension(resolutionHeight, RESOLUTION_DEFAULT_HEIGHT);
  const windowWidth = Math.max(40, Math.round((geometry?.w ?? 480) > 0 ? (geometry?.w ?? 480) : 480));
  const windowHeight = Math.max(40, Math.round((geometry?.h ?? 320) > 0 ? (geometry?.h ?? 320) : 320));
  const axisX = resolveGeometryAxis(geometry?.x ?? -1, safeResolutionWidth, windowWidth);
  const axisY = resolveGeometryAxis(geometry?.y ?? -1, safeResolutionHeight, windowHeight);
  return {
    resolutionWidth: safeResolutionWidth,
    resolutionHeight: safeResolutionHeight,
    windowWidth,
    windowHeight,
    left: axisX.value,
    top: axisY.value,
    xMode: axisX.mode,
    yMode: axisY.mode,
    xRaw: geometry?.x ?? -1,
    yRaw: geometry?.y ?? -1,
  };
}

function formatNuiRectNumber(value: number): string {
  if (!Number.isFinite(value)) return "0.0";
  const fixed = value.toFixed(4);
  const trimmed = fixed.replace(/\.?0+$/, "");
  return trimmed.includes(".") ? trimmed : `${trimmed}.0`;
}

function formatNuiRectValue(rect: PreviewNuiRect): string {
  return `NuiRect(${formatNuiRectNumber(rect.x)}, ${formatNuiRectNumber(rect.y)}, ${formatNuiRectNumber(rect.w)}, ${formatNuiRectNumber(rect.h)})`;
}

function formatNuiVecNumber(value: number): string {
  if (!Number.isFinite(value)) return "0.0";
  const fixed = value.toFixed(4);
  const trimmed = fixed.replace(/\.?0+$/, "");
  return trimmed.includes(".") ? trimmed : `${trimmed}.0`;
}

function formatNuiVecValue(vec: PreviewNuiVec): string {
  return `NuiVec(${formatNuiVecNumber(vec.x)}, ${formatNuiVecNumber(vec.y)})`;
}

function isNearly(value: number, target: number): boolean {
  return Math.abs(value - target) <= 0.0001;
}

function geometryAnchorLabel(value: number): string | null {
  if (isNearly(value, -1.0)) return "center";
  if (isNearly(value, -2.0)) return "cursor TL";
  if (isNearly(value, -3.0)) return "cursor C";
  return null;
}

function previewColorValue(raw: string | undefined, fallback = "rgba(206, 220, 241, 1)"): string {
  const parsed = parseNuiColorLiteral(raw);
  if (!parsed) return fallback;
  return `rgba(${clampByte(parsed.r)}, ${clampByte(parsed.g)}, ${clampByte(parsed.b)}, ${clampByte(parsed.a) / 255})`;
}

function previewColorValueForRender(raw: string | undefined, fallback: string, renderCtx: LiveRenderContext): string {
  const value = String(raw ?? "").trim();
  const bind = parseNuiBindDescriptor(value);
  if (bind && typeof renderCtx.listRowIndex === "number" && renderCtx.previewBinds?.[bind.id]) {
    const rowValue = renderCtx.previewBinds[bind.id][renderCtx.listRowIndex];
    if (rowValue && typeof rowValue === "object" && !Array.isArray(rowValue)) {
      const color = rowValue as JuiImportObject;
      const r = readJuiNumber(color.r);
      const g = readJuiNumber(color.g);
      const b = readJuiNumber(color.b);
      const a = readJuiNumber(color.a) ?? 255;
      if (r !== null && g !== null && b !== null) {
        return `rgba(${clampByte(r)}, ${clampByte(g)}, ${clampByte(b)}, ${clampByte(a) / 255})`;
      }
    }
  }
  return previewColorValue(raw, fallback);
}

function previewSwapViewLabel(viewNode: NuiNode, index: number): string {
  const fallback = `View ${index + 1}`;
  const raw = String(viewNode.props.jViewLabel ?? "").trim();
  if (!raw) return fallback;
  const literal = parseJsonStringLiteral(raw);
  if (literal !== null && literal.trim()) return literal.trim();
  const bind = parseNuiBindDescriptor(raw);
  if (bind?.id.trim()) return bind.id.trim();
  return fallback;
}

function parseImportedNode(
  raw: unknown,
  allowedComponents: Set<string>,
  path: string,
  errors: string[],
): NuiNode | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    errors.push(`${path}: expected node object.`);
    return null;
  }
  const source = raw as Record<string, unknown>;
  if (typeof source.componentName !== "string" || !source.componentName.trim()) {
    errors.push(`${path}: missing componentName.`);
    return null;
  }
  if (!allowedComponents.has(source.componentName)) {
    errors.push(`${path}: unknown componentName '${source.componentName}'.`);
    return null;
  }

  const id = typeof source.id === "string" && source.id.trim() ? source.id : `node_import_${Math.random().toString(36).slice(2, 10)}`;
  const props: Record<string, string> = {};
  if (source.props && (typeof source.props !== "object" || Array.isArray(source.props))) {
    errors.push(`${path}: props must be an object.`);
  } else if (source.props && typeof source.props === "object") {
    for (const [key, value] of Object.entries(source.props as Record<string, unknown>)) {
      props[key] = String(value ?? "");
    }
  }

  if (source.children !== undefined && !Array.isArray(source.children)) {
    errors.push(`${path}: children must be an array.`);
  }
  const childrenRaw = Array.isArray(source.children) ? source.children : [];
  const children = childrenRaw
    .map((child, idx) => parseImportedNode(child, allowedComponents, `${path}.children[${idx}]`, errors))
    .filter((child): child is NuiNode => Boolean(child));

  return {
    id,
    componentName: source.componentName,
    props,
    children,
  };
}

function computeNextNodeSeq(nodes: NuiNode[]): number {
  let maxSeq = 0;

  function walk(list: NuiNode[]): void {
    for (const node of list) {
      const match = node.id.match(/^node_(\d+)$/);
      if (match) {
        maxSeq = Math.max(maxSeq, Number(match[1]));
      }
      walk(node.children);
    }
  }

  walk(nodes);
  return maxSeq + 1;
}

function collectNodeIds(nodes: NuiNode[], sink: Set<string> = new Set()): Set<string> {
  for (const node of nodes) {
    sink.add(node.id);
    collectNodeIds(node.children, sink);
  }
  return sink;
}

function countDuplicateNodeIds(nodes: NuiNode[]): number {
  const counts = new Map<string, number>();
  const walk = (list: NuiNode[]): void => {
    for (const node of list) {
      counts.set(node.id, (counts.get(node.id) ?? 0) + 1);
      walk(node.children);
    }
  };
  walk(nodes);
  let duplicates = 0;
  for (const count of counts.values()) {
    if (count > 1) duplicates += count - 1;
  }
  return duplicates;
}

function rewriteDuplicateNodeIds(nodes: NuiNode[]): { rootNodes: NuiNode[]; replacedCount: number; nextSeq: number } {
  const cloned = cloneForest(nodes);
  const seen = new Set<string>();
  let seq = Math.max(1, computeNextNodeSeq(cloned));
  let replacedCount = 0;

  const nextUniqueId = (): string => {
    let id = `node_${seq}`;
    seq += 1;
    while (seen.has(id)) {
      id = `node_${seq}`;
      seq += 1;
    }
    return id;
  };

  const walk = (list: NuiNode[]): void => {
    for (const node of list) {
      if (seen.has(node.id)) {
        node.id = nextUniqueId();
        replacedCount += 1;
      }
      seen.add(node.id);
      walk(node.children);
    }
  };
  walk(cloned);

  return { rootNodes: cloned, replacedCount, nextSeq: seq };
}

function snapshotChanged(before: HistorySnapshot, after: HistorySnapshot): boolean {
  return JSON.stringify(before) !== JSON.stringify(after);
}

function resolveRootDirectionToBase(rawDirection: string | undefined): "NuiCol" | "NuiRow" {
  const value = String(rawDirection ?? "").trim().toUpperCase();
  if (!value) return "NuiCol";
  if (value === NUI_ROOT_DIRECTION_ROW) return "NuiRow";
  if (value === NUI_ROOT_DIRECTION_COL) return "NuiCol";
  if (value.includes("ROW")) return "NuiRow";
  if (value.includes("COL")) return "NuiCol";
  if (value.includes("HORIZONTAL")) return "NuiRow";
  if (value.includes("VERTICAL")) return "NuiCol";
  if (value === "1") return "NuiRow";
  if (value === "0") return "NuiCol";
  return "NuiCol";
}

function resolveRootNodeAsBase(node: NuiNode): "NuiCol" | "NuiRow" {
  return resolveRootDirectionToBase(node.props.nDirection);
}

function resolveSwapNodeAsBase(node: NuiNode): "NuiCol" | "NuiRow" {
  return resolveRootDirectionToBase(node.props.nDirection);
}

function resolveListCellNodeAsBase(node: NuiNode): "NuiCol" | "NuiRow" {
  const rawDirection = String(node.props.nDirection ?? "").trim();
  if (!rawDirection) return "NuiRow";
  return resolveRootDirectionToBase(rawDirection);
}

